@test("SHADOW-FAST-SETTLE — shadow_bets settle on the 15-min settle_ready cadence, not only at 21:00 UTC")
def _():
    """Before this fix, `_settle_pending_shadow_bets` was called only from
    `run_settlement` (once daily at 21:00 UTC), so shadow_bets sat 6-8h in
    'pending' between match finish and the batch. Fix: also call it from
    `settle_finished_matches` (invoked by settle_ready every 15 min AND
    inline from the live poller). Guards:
      (1) settle_finished_matches queries _PENDING_SHADOW_BETS_SQL scoped to
          the match_ids it's settling,
      (2) calls _settle_pending_shadow_bets with finished=[] (score comes
          from matches.score_home/score_away via the SQL),
      (3) wrapped in try/except so a shadow-settle failure never blocks
          the real-bet settlement chain — same discipline as the
          run_settlement daily-batch path.
    """
    import inspect
    from workers.jobs import settlement
    src = inspect.getsource(settlement.settle_finished_matches)
    assert "SHADOW-FAST-SETTLE-2026-08-19" in src, (
        "shadow fast-settle marker missing — bets on finished matches would sit "
        "'pending' for 6-8h until the 21:00 UTC batch"
    )
    assert "_PENDING_SHADOW_BETS_SQL" in src and "sb.match_id = ANY" in src, (
        "shadow settlement must query pending shadow bets scoped to the match_ids being settled"
    )
    assert "_settle_pending_shadow_bets" in src, (
        "settle_finished_matches must invoke _settle_pending_shadow_bets"
    )
    # Must be wrapped so a shadow failure never blocks real-bet settlement
    lines = src.split("\n")
    shadow_line = next(i for i, l in enumerate(lines) if "_settle_pending_shadow_bets" in l)
    # Walk back to find enclosing try/except
    try_found = any("try:" in l for l in lines[max(0, shadow_line - 10) : shadow_line])
    except_found = any("except" in l for l in lines[shadow_line : min(len(lines), shadow_line + 8)])
    assert try_found and except_found, (
        "shadow settle call must be wrapped in try/except so a failure doesn't block real-bet settlement"
    )


@test("CLV-AUTOVOID — settlement voids bets where odds_at_pick/closing_odds ≥ 1.65× (data-error safety net)")
def _():
    """Post-settlement safety net for fantasy pre-match prices. Any settled
    bet where odds_at_pick / closing_odds ≥ 1.65 (CLV ≥ 65%) is almost
    certainly a data error — placement's ODDS-OUTLIER-FILTER catches this
    class at pick time, but pre-filter picks and future filter regressions
    need a belt-and-braces catch at settlement. Motivated by the 2026-08-19
    retroactive sweep of 4 bets (Gremio-U20 Coolbet-teams-swapped, Sudtirol,
    Hapoel Ramat Gan, Bognor Regis) where pick prices were nowhere near the
    closing sharp line.

    Guards:
      (1) helper exists and is called from run_settlement after
          _settle_pending_bets, wrapped in try/except (non-fatal),
      (2) threshold constant is 1.65,
      (3) update uses execute_write_returning (not execute_query — which
          doesn't commit, per the 2026-06 COOLBET-INLINE-HEAL-BUTTONS bug),
      (4) idempotent via result IN ('won','lost'); the void is a quarantine (#162 W1.1),
      (5) only touches won/lost rows (not pending, not already void),
      (6) closing_odds NOT NULL + > 0 guard,
      (7) sets result='void' AND pnl=0 so the void drops from headline ROI.
    """
    import inspect
    from workers.jobs import settlement
    # Helper exists + threshold + execute_write_returning
    assert hasattr(settlement, "_apply_clv_autovoid"), "_apply_clv_autovoid missing"
    assert getattr(settlement, "CLV_AUTOVOID_RATIO_THRESHOLD", None) == 1.65, (
        "CLV_AUTOVOID_RATIO_THRESHOLD must be 1.65"
    )
    helper_src = inspect.getsource(settlement._apply_clv_autovoid)
    assert "execute_write_returning" in helper_src, (
        "CLV-AUTOVOID: must use execute_write_returning (execute_query does NOT commit)"
    )
    # Idempotency + row-guard clauses
    # #162 W1.1 (2026-09-25): idempotency now comes from `result IN ('won','lost')` (a voided row is never
    # matched again) — the old "skip rows already tagged" clause is gone ON PURPOSE so a row the resettle
    # pass re-graded is re-judged; the void is a quarantine resettle skips (CLV-AUTOVOID-STICKS).
    assert "NOT LIKE '%%CLV-AUTOVOID%%'" not in helper_src.split("WITH hit AS")[1].split("), voided AS")[0], (
        "CLV-AUTOVOID: must not skip previously tagged rows (they are re-judged)"
    )
    assert "void_reason = 'quarantine: clv-autovoid" in helper_src, "CLV-AUTOVOID: the void must be a quarantine"
    assert "result IN ('won', 'lost')" in helper_src, (
        "CLV-AUTOVOID: must only touch won/lost rows (not pending, not already void)"
    )
    assert "closing_odds IS NOT NULL" in helper_src and "closing_odds > 0" in helper_src, (
        "CLV-AUTOVOID: closing_odds NULL/zero guard missing"
    )
    assert "result   = 'void'" in helper_src or "result = 'void'" in helper_src, (
        "CLV-AUTOVOID: must set result='void'"
    )
    assert "pnl      = 0" in helper_src or "pnl = 0" in helper_src, (
        "CLV-AUTOVOID: must zero the pnl so void drops from headline ROI"
    )
    # Called from run_settlement, non-fatal
    run_src = inspect.getsource(settlement.run_settlement)
    assert "_apply_clv_autovoid" in run_src, (
        "CLV-AUTOVOID: helper must be invoked from run_settlement"
    )
    assert "CLV-AUTOVOID-2026-08-19" in run_src, (
        "CLV-AUTOVOID: run_settlement hook must carry the CLV-AUTOVOID-2026-08-19 marker"
    )


@test("ODDS-OUTLIER-FILTER — 1X2/BTTS/DC offers rejected when far above Pinnacle-or-median consensus")
def _():
    """Placement-layer must drop non-Pinnacle 1X2 / BTTS / DC offers priced above
    anchor × ceiling multiplier, where anchor = Pinnacle odds if present else the
    median across ≥3 accessible-book offers. Motivation (2026-08-18): flagged
    example — Hapoel Ramat Gan home win listed at Marathonbet 4.50 (+22% edge)
    when Coolbet consensus was ~2.60. Filter must:
      (1) declare per-market ceiling multipliers (1x2 / btts / double_chance),
      (2) require ≥3 accessible books when Pinnacle is absent (min-books gate),
      (3) reject non-Pinnacle offers exceeding anchor × multiplier,
      (4) exempt Pinnacle itself (it IS the anchor when present),
      (5) log a reject counter so the operator can see outliers being dropped.
    """
    import inspect
    from workers.jobs import daily_pipeline_v2
    src = inspect.getsource(daily_pipeline_v2._load_today_from_db)
    assert "ODDS-OUTLIER-FILTER-2026-08-18" in src, (
        "ODDS-OUTLIER-FILTER: marker missing — outlier rejection not wired into _load_today_from_db"
    )
    # OUTLIER-CEILING-CALIBRATED-2026-09-16: was 1.35/1.30/1.35, picked by
    # judgement in 2026-08 and never measured. Measured on 12,573 settled shadow
    # bets over 120d, bucketing each by taken_price/anchor and comparing the
    # ACTUAL win rate to the rate the taken price implies, controlled for odds
    # level. The 1.25-1.35 band -- accepted under the old ceiling -- ran a gap of
    # -6.2 points at odds 2.2-3.2 and -14.3 at odds >3.2, for -18.1% and -56.0%
    # ROI. Tightening to 1.25 removes 376 bets averaging -34.0% ROI.
    assert '"1x2": 1.25' in src and '"btts": 1.25' in src and '"double_chance": 1.25' in src, (
        "ODDS-OUTLIER-FILTER: per-market ceiling multipliers must be 1.25 "
        "(OUTLIER-CEILING-CALIBRATED-2026-09-16). Raising them re-admits a band "
        "measured at -18% to -56% ROI; lowering them cuts into 1.05-1.25, which "
        "the same measurement shows is the PROFITABLE band in every odds bucket. "
        "Re-run the calibration before changing either way."
    )
    # The band below the ceiling is load-bearing, not slack. A future tightening
    # to 1.10/1.15 was proposed and REJECTED by the measurement -- it would have
    # deleted the only band with a positive gap. Pin that reasoning so the next
    # reader does not re-derive it from intuition.
    assert "1.05-1.25 is the PROFITABLE band" in src, (
        "ODDS-OUTLIER-FILTER: the calibration finding must stay next to the "
        "constants -- the ceiling is a measured value, not a guess")
    assert "_OUTLIER_MIN_BOOKS = 3" in src, (
        "ODDS-OUTLIER-FILTER: min-books gate for median anchor must be 3"
    )
    assert "from statistics import median" in src, (
        "ODDS-OUTLIER-FILTER: median anchor requires statistics.median import"
    )
    assert "outlier_anchor" in src and 'next((o for b, o in offers if b == "Pinnacle")' in src, (
        "ODDS-OUTLIER-FILTER: anchor selection must prefer Pinnacle before falling back to median"
    )
    assert 'bookmaker != "Pinnacle" and odds_val > _anchor * _mult' in src, (
        "ODDS-OUTLIER-FILTER: rejection check must exempt Pinnacle and apply ceiling multiplier"
    )
    assert "outlier_rejects" in src, (
        "ODDS-OUTLIER-FILTER: reject counter missing — operator would not see outliers being dropped"
    )


@test("ODDS-QUALITY-CLEANUP — filter drops unused OU markets and extreme AH lines")
def _():
    """filter_garbage_ou_rows must drop OU variants not in ALLOWED_OU_MARKETS
    and AH lines beyond ±MAX_AH_LINE, while keeping the four used OU markets
    and AH lines within range."""
    from workers.utils.odds_quality import filter_garbage_ou_rows, ALLOWED_OU_MARKETS, MAX_AH_LINE
    rows = [
        # Unused OU market — must be dropped
        {"bookmaker": "Bet365", "market": "over_under_275", "selection": "over",  "odds": 1.80},
        {"bookmaker": "Bet365", "market": "over_under_275", "selection": "under", "odds": 2.05},
        # Used OU market — must be kept (valid pair)
        {"bookmaker": "Bet365", "market": "over_under_25", "selection": "over",  "odds": 1.90},
        {"bookmaker": "Bet365", "market": "over_under_25", "selection": "under", "odds": 1.95},
        # AH line within ±3.0 — must be kept
        {"bookmaker": "Pinnacle", "market": "asian_handicap", "selection": "home", "odds": 1.92, "handicap_line": -1.5},
        # AH line beyond ±3.0 — must be dropped
        {"bookmaker": "Pinnacle", "market": "asian_handicap", "selection": "home", "odds": 1.05, "handicap_line": -5.0},
        # 1x2 — always kept
        {"bookmaker": "Pinnacle", "market": "1x2", "selection": "home", "odds": 2.10},
    ]
    out = filter_garbage_ou_rows(rows)
    markets = [(r["market"], r.get("handicap_line")) for r in out]
    assert ("over_under_275", None) not in [(r["market"], None) for r in out], "unused OU market must be dropped"
    assert any(r["market"] == "over_under_25" for r in out), "allowed OU market must be kept"
    assert any(r.get("handicap_line") == -1.5 for r in out), "AH line within ±3.0 must be kept"
    assert not any(r.get("handicap_line") == -5.0 for r in out), "AH line beyond ±3.0 must be dropped"
    assert any(r["market"] == "1x2" for r in out), "1x2 must always pass through"
    assert MAX_AH_LINE == 3.0, "MAX_AH_LINE must be 3.0"
    assert "over_under_25" in ALLOWED_OU_MARKETS and "over_under_15" in ALLOWED_OU_MARKETS


