@test("TONYBET-SWEEPER — market mapping, squad naming, flip guard, and the fences around a new book")
def test_tonybet_sweeper():
    """TONYBET-SWEEPER (#101, 2026-09-23). Tonybet is swept on Sportradar UOF ids
    (vendorMarketId + vendorOutcomeId), never Tonybet's internal market ids. Pins:
    the mapping into the shared vocabulary; that quarter totals and absurd Asian
    lines are NOT stored; that suspended/inactive prices are skipped; that women's
    and youth teams get the qualifier our squad guard reads (Tonybet names them
    WITHOUT one); that side-flipped pairings are detected; and the two fences — not
    in the pre-registered forward test's book set, and watched for staleness."""
    import pathlib
    from workers.automation import tonybet_feed as t

    def mk(vm, spec, outs, status=1):
        return {"vendorMarketId": vm, "specifiers": spec, "status": status,
                "outcomes": [{"vendorOutcomeId": o, "odds": p, "probabilities": q,
                              "active": a} for o, p, q, a in outs]}
    markets = [
        mk(1, None, [("1", 2.3, 0.41, 1), ("2", 3.05, 0.31, 1), ("3", 3.3, 0.28, 1)]),
        mk(18, "total=2.5", [("12", 2.47, 0.37, 1), ("13", 1.5, 0.63, 1)]),
        mk(18, "total=2.25", [("12", 2.16, 0.43, 1), ("13", 1.65, 0.57, 1)]),   # quarter → own label (#130)
        mk(16, "hcp=-0.5", [("1714", 2.25, 0.41, 1), ("1715", 1.6, 0.59, 1)]),
        mk(16, "hcp=-2", [("1714", 9.0, 0.07, 1), ("1715", 1.04, 0.93, 1)]),    # absurd → dropped
        mk(29, None, [("74", 2.1, 0.44, 1), ("76", 1.69, 0.56, 0)]),           # 'no' inactive
        mk(10, None, [("9", 1.3, 0.72, 1), ("10", 1.35, 0.69, 1), ("11", 1.54, 0.59, 1)]),
        mk(11, None, [("4", 1.6, 0.59, 1), ("5", 2.26, 0.41, 1)]),
        mk(1, None, [("1", 9.0, 0.1, 1)], status=-1),                            # suspended
        mk(14, "hcp=0:1", [("1711", 4.8, 0.18, 1)]),                             # European hcp → ignored
    ]
    got = {(r[0], r[1], r[3]): (r[2], r[4]) for r in t.parse_markets(markets)}
    assert got[("1x2", "home", None)] == (2.3, 0.41)
    assert ("over_under_25", "over", 2.5) in got and ("over_under_25", "under", 2.5) in got
    # #130 (owner 2026-09-24, "all OU lines"): quarter totals ARE stored now — under their
    # OWN label with the line beside it, never under a .5 label.
    assert ("over_under_225", "over", 2.25) in got, "quarter FT total not stored (#130)"
    assert not any(k[2] == 2.25 and k[0] != "over_under_225" for k in got), \
        "quarter total leaked into the .5 vocabulary"
    assert ("asian_handicap", "home", -0.5) in got and ("asian_handicap", "away", -0.5) in got
    assert not any(k[0] == "asian_handicap" and k[2] == -2.0 for k in got), "absurd AH line stored"
    assert ("btts", "yes", None) in got and ("btts", "no", None) not in got, "inactive outcome stored"
    assert {k[1] for k in got if k[0] == "double_chance"} == {"1x", "12", "x2"}
    assert {k[1] for k in got if k[0] == "draw_no_bet"} == {"home", "away"}
    assert got[("1x2", "home", None)][0] != 9.0, "suspended market overwrote a live price"

    assert t._team_name({"name": "Olympique Lyon", "gender": 2}) == "Olympique Lyon W"
    assert t._team_name({"name": "Romania", "gender": 1, "ageGroup": "U19"}) == "Romania U19"
    assert t._team_name({"name": "Some Academy", "gender": 1, "ageGroup": "YOUTH"}) is None
    assert t._flipped("Arsenal", "Chelsea", {"home": "Chelsea FC", "away": "Arsenal FC"})
    assert not t._flipped("Arsenal", "Chelsea", {"home": "Arsenal FC", "away": "Chelsea FC"})

    root = pathlib.Path(__file__).parent.parent
    sched = (root / "workers/scheduler.py").read_text()
    reg = sched[sched.index('id="tonybet_odds_snapshot"') - 250: sched.index('id="tonybet_odds_snapshot"')]
    assert 'minute="1,31"' in reg and "_tonybet_odds_snapshot_wrapper" in reg
    pub = (root / "scripts/publish_picks_forward_test.py").read_text()
    excl = pub[pub.index("EXCLUDED_BOOKS = ("): pub.index("MARKETS = {")]
    # Let in 2026-09-23 with the owner's go-ahead: the locked rule is "all books,
    # phantom feeds excluded by name", and Tonybet is site-verified, not phantom.
    assert '"Tonybet"' not in excl, ("Tonybet is a verified real book — excluding it "
                                     "departs from the pre-registered 'all books' rule")
    from workers.jobs.health_alerts import DIRECT_FEED_BOOKS
    assert "Tonybet" in DIRECT_FEED_BOOKS
    # Promoted 2026-09-23 after the site-price check (14/15 identical).
    pipe = (root / "workers/jobs/daily_pipeline_v2.py").read_text()
    acc = pipe[pipe.index("ACCESSIBLE_BOOKMAKERS: frozenset"): pipe.index("PRICE_REFERENCE_BOOKMAKERS")]
    assert '"Tonybet"' in acc, "Tonybet left the placeable set"
    assert (root / "supabase/migrations/383_book_fair_probs.sql").exists()

    # PHASE 1b: the full-board families, on Sportradar ids confirmed in the catalogue.
    deep = [
        mk(166, "total=9.5", [("12", 1.9, 0.5, 1), ("13", 1.9, 0.5, 1)]),
        mk(167, "total=4.5", [("12", 1.8, 0.52, 1), ("13", 2.0, 0.48, 1)]),
        mk(177, "total=4", [("12", 1.85, 0.5, 1), ("13", 1.95, 0.5, 1)]),
        mk(165, "hcp=-1.5", [("1714", 1.9, 0.5, 1), ("1715", 1.9, 0.5, 1)]),
        mk(139, "total=3.5", [("12", 1.9, 0.5, 1), ("13", 1.9, 0.5, 1)]),
        mk(19, "total=1.5", [("12", 2.0, 0.48, 1), ("13", 1.8, 0.52, 1)]),
        mk(68, "total=0.5", [("12", 1.4, 0.7, 1), ("13", 2.9, 0.3, 1)]),
        mk(90, "total=1.5", [("12", 2.2, 0.44, 1), ("13", 1.65, 0.56, 1)]),
        mk(60, None, [("1", 3.0, 0.3, 1), ("2", 2.1, 0.45, 1), ("3", 4.0, 0.25, 1)]),
        mk(83, None, [("1", 2.8, 0.33, 1), ("2", 2.4, 0.4, 1), ("3", 3.6, 0.27, 1)]),
        mk(75, None, [("74", 4.5, 0.2, 1), ("76", 1.2, 0.8, 1)]),
        mk(63, None, [("9", 1.3, 0.75, 1), ("10", 1.4, 0.7, 1), ("11", 1.6, 0.55, 1)]),
        mk(166, "total=9.25", [("12", 1.9, 0.5, 1), ("13", 1.9, 0.5, 1)]),     # quarter → dropped
    ]
    dk = {(r[0], r[1]) for r in t.parse_markets(deep)}
    for need in [("corners_ou_95", "over"), ("corners_home_ou_45", "under"),
                 ("corners_1h_ou_40", "over"), ("corners_handicap", "home"),
                 ("bookings_ou_35", "over"), ("team_total_home_15", "over"),
                 ("over_under_1h_05", "over"), ("over_under_2h_15", "under"),
                 ("1x2_1h", "draw"), ("1x2_2h", "away"), ("btts_1h", "yes"),
                 ("double_chance_1h", "x2")]:
        assert need in dk, f"phase-1b family missing: {need}"
    assert not any(k[0].startswith("cards_") for k in dk), (
        "Sportradar 'bookings' must not be filed as cards_* — its counting rule is unproven")
    assert not any(k[0] == "corners_ou_92" for k in dk), "quarter corner line stored"
    assert t._in_deep_window(30) and t._in_deep_window(180) and not t._in_deep_window(600)

    # PHASE 2: live + results, archived, scheduled, and the close via near-kickoff.
    src = (root / "workers/automation/tonybet_feed.py").read_text()
    for fn in ("run_live", "run_results", "fetch_deep_markets"):
        assert callable(getattr(t, fn, None)), f"{fn} missing"
    assert '_archive("live"' in src and '_archive("results"' in src and '_archive("deep"' in src
    assert 'id="tonybet_live"' in sched and "IntervalTrigger(seconds=120)" in sched
    assert 'id="tonybet_results"' in sched
    nk_src = (root / "workers/jobs/near_kickoff_capture.py").read_text()
    assert '"Tonybet": capture_tonybet' in nk_src
    assert (root / "supabase/migrations/385_book_live_stats_and_results.sql").exists()

    # RAW ARCHIVE: every fetched page is kept so later parsers can rebuild history.
    import gzip, tempfile
    src = (root / "workers/automation/tonybet_feed.py").read_text()
    assert '_archive("prematch", page, r.content)' in src, "raw responses are no longer archived"
    old_dir = t._RAW_DIR
    try:
        t._RAW_DIR = tempfile.mkdtemp()
        t._archive("prematch", 1, b'{"ok":1}')
        files = list(pathlib.Path(t._RAW_DIR).rglob("*.json.gz"))
        assert len(files) == 1 and gzip.decompress(files[0].read_bytes()) == b'{"ok":1}'
    finally:
        t._RAW_DIR = old_dir

@test("FEED-REGISTRY-COVERS-SWEEPERS — every sweeper is in the feed registry, and empty sweeps fail")
def test_feed_registry_covers_sweepers():
    """FEEDS-DASHBOARD (#107, 2026-09-23). /admin/feeds shows only what
    workers/registry/feed_registry.py lists, so a sweeper added without an entry is
    invisible — the exact blind spot that let Coolbet sit silent for 4 h (#108).
    Pins: (1) every odds / live / results sweep registered in the scheduler has a
    registry entry; (2) every book the staleness alert watches has a feed; (3) each
    registry job name really is a scheduled _run_job name; (4) Coolbet and Epicbet
    sweeps FAIL when they store nothing for 20+ fixtures (they used to 'complete')."""
    import pathlib, re
    from workers.registry.feed_registry import FEEDS, FEEDS_BY_ID
    from workers.jobs.health_alerts import DIRECT_FEED_BOOKS
    root = pathlib.Path(__file__).parent.parent
    sched = (root / "workers/scheduler.py").read_text()

    assert len(FEEDS_BY_ID) == len(FEEDS), "duplicate feed id in the registry"
    for f in FEEDS:
        assert f["health"] in ("data", "runs", "service"), f["id"]
        assert f["category"] in ("book", "af", "infra"), f["id"]
        if f.get("job"):
            # Most feeds log through _run_job; a few (fetch_fixtures) log from inside
            # the pipeline. Either way the name must be one the engine really writes.
            logged = f'_run_job("{f["job"]}"' in sched or any(
                f'"{f["job"]}"' in p.read_text() for p in (root / "workers").rglob("*.py")
                if "registry" not in p.parts)
            assert logged, f"registry job {f['job']!r} ({f['id']}) is never logged by the engine"

    registered_jobs = {f.get("job") for f in FEEDS}
    sweeper_ids = set(re.findall(r'id="((?:\w+_)?(?:odds_snapshot|site_odds|live|results))"', sched))
    sweeper_ids -= {"live_poller"}
    run_names = set(re.findall(r'_run_job\("(\w+)"', sched))
    for sid in sweeper_ids:
        if sid in run_names:
            assert sid in registered_jobs, f"sweeper job {sid!r} has no feed_registry entry"

    fed_books = {f.get("book") for f in FEEDS}
    for b in DIRECT_FEED_BOOKS:
        assert b in fed_books, f"{b} is watched for staleness but has no feed entry"

    assert 'id="feed_health"' in sched
    assert (root / "supabase/migrations/388_feed_status.sql").exists()
    cool = sched[sched.index("def job_coolbet_odds_snapshot"):sched.index("def _coolbet_odds_snapshot_wrapper")]
    assert "fixtures >= 10 and not stored" in cool and "raise RuntimeError" in cool and "refresh_skipped" in cool, (
        "the Coolbet sweep must fail when it stores nothing")
    epic = sched[sched.index("def job_epicbet_odds_snapshot"):sched.index("def _epicbet_odds_snapshot_wrapper")]
    assert "raise RuntimeError" in epic, "the Epicbet sweep must fail when it stores nothing"

@test("FEED-CONTROLS — pause is enforced in _run_job, run-now is drained safely, alerts fire on transitions only")
def test_feed_controls():
    """FEEDS-DASHBOARD phase B (#107, 2026-09-23). /admin/feeds only writes requests
    to feed_controls; the engine enforces them. Pins: the pause check sits at the
    top of _run_job (the one place every feed job passes through); run-now is
    refused for a paused feed or one without the control; Telegram alerts fire on
    TRANSITIONS only (newly red, or recovered) and never for a paused feed."""
    import pathlib, time
    from workers.jobs import feed_control as fc
    from workers.jobs import feed_health as fh
    root = pathlib.Path(__file__).parent.parent
    sched = (root / "workers/scheduler.py").read_text()

    rj = sched[sched.index("def _run_job("):sched.index("log_pipeline_start(name")]
    assert "is_job_paused(name)" in rj and "return" in rj, "pause must be checked before the run is logged"
    assert 'id="feed_control_drain"' in sched and "IntervalTrigger(seconds=30)" in sched
    assert "_SCHEDULER = scheduler" in sched
    assert (root / "supabase/migrations/389_feed_controls.sql").exists()

    # is_job_paused: paused feed's job resolves, others do not (cache primed, no DB).
    saved = dict(fc._cache)
    try:
        fc._cache.update(at=time.monotonic(), paused={"coolbet_prematch"})
        assert fc.is_job_paused("coolbet_odds_snapshot")
        assert not fc.is_job_paused("epicbet_odds_snapshot")
        assert not fc.is_job_paused("fetch_fixtures"), "a feed without the pause control was paused"
    finally:
        fc._cache.clear(); fc._cache.update(saved)

    # drain: paused → refused; no control → refused; otherwise a one-off job.
    calls, writes = [], []
    class S:
        def add_job(self, fn, **kw): calls.append((fn, kw["id"]))
    class M:
        _tonybet_live_wrapper = staticmethod(lambda: None)
    orig_q, orig_w = fc.execute_query, fc.execute_write
    try:
        fc.execute_query = lambda *a, **k: [
            {"feed_id": "coolbet_prematch", "paused": True, "run_now_requested_by": "t"},
            {"feed_id": "af_fixtures", "paused": False, "run_now_requested_by": "t"},
            {"feed_id": "tonybet_live", "paused": False, "run_now_requested_by": "t"}]
        fc.execute_write = lambda *a, **k: writes.append(a) or 1
        orig_ar = fc.auto_resume
        fc.auto_resume = lambda: 0      # covered by FEED-AUTO-PAUSE
        try:
            res = fc.drain(S(), M())
        finally:
            fc.auto_resume = orig_ar
    finally:
        fc.execute_query, fc.execute_write = orig_q, orig_w
    assert (res["started"], res["refused"]) == (1, 2), res
    assert calls and calls[0][1] == "runnow_tonybet_live"

    # alerts: only transitions to fail / fail→ok, never for paused.
    import workers.notify.telegram as tg
    sent = []
    orig_send = tg.send_telegram
    try:
        tg.send_telegram = lambda msg, **k: sent.append(msg)
        n = fh._alert_transitions(
            {"coolbet_prematch": "ok", "epicbet_prematch": "fail", "tonybet_live": "fail",
             "af_odds": "ok", "unibet_prematch": "ok"},
            [{"feed_id": "coolbet_prematch", "status": "fail", "status_reason": "no data"},
             {"feed_id": "epicbet_prematch", "status": "ok"},
             {"feed_id": "tonybet_live", "status": "fail"},        # already red → silent
             {"feed_id": "af_odds", "status": "warn"},             # warn → silent
             {"feed_id": "unibet_prematch", "status": "paused"}])  # paused → silent
    finally:
        tg.send_telegram = orig_send
    assert n == 2 and "failing" in sent[0] and "recovered" in sent[1], sent

    # A brand-new runs-judged job with no runs yet reads "waiting", never red.
    from workers.registry.feed_registry import FEEDS_BY_ID
    orig_u = fh._unit_state
    try:
        fh._unit_state = lambda u: "active"
        row = fh._evaluate_one(FEEDS_BY_ID["tonybet_results"], [], {})
    finally:
        fh._unit_state = orig_u
    assert row["status"] == "unknown" and "first scheduled run" in row["status_reason"], row

@test("FEED-AUTO-PAUSE — bot-protected sweeps pause themselves, back off, and test again")
def test_feed_auto_pause():
    """#107 / #108 (2026-09-23). A bot-protection flag on our exit IP is cured only by
    time without traffic — #108 showed a full FlareSolverr restart does not help — and
    every retry keeps it fresh. So: 2 failed runs in a row → auto-pause with backoff
    1/2/4/8/12 h → auto-resume with one test run → re-pause (doubled) if it fails,
    reset once it succeeds. Pins those rules and that an operator's pause is never
    touched."""
    from datetime import datetime, timedelta, timezone
    from workers.jobs import feed_control as fc
    assert [fc._backoff(n) for n in (1, 2, 3, 4, 5, 9)] == [60, 120, 240, 480, 720, 720]

    now = datetime.now(timezone.utc)
    writes = []
    orig_q, orig_w, orig_n = fc.execute_query, fc.execute_write, fc._notify
    try:
        fc.execute_write = lambda sql, params=None: writes.append((sql, params)) or 1
        fc._notify = lambda msg, key: None
        def run(ctl_rows, evals):
            writes.clear()
            fc.execute_query = lambda *a, **k: ctl_rows
            return fc.apply_auto_pause(evals)

        fail2 = {"feed_id": "coolbet_prematch", "fail_streak": 2, "last_run_at": now,
                 "last_run_status": "failed", "status": "fail", "last_error": "blocked"}
        # 2 failures, no prior pause → paused for 60 min
        r = run([], [fail2])
        assert r["auto_paused"] == 1 and any("paused for 60 min" in str(p) for _, p in writes), writes
        # 1 failure → nothing
        assert run([], [dict(fail2, fail_streak=1)])["auto_paused"] == 0
        # a feed without auto_pause (Tonybet live) → nothing
        assert run([], [dict(fail2, feed_id="tonybet_live")])["auto_paused"] == 0
        # failures that predate the last auto-resume do not re-pause (the test run is pending)
        ctl = [{"feed_id": "coolbet_prematch", "paused": False, "paused_by": None,
                "auto_pause_count": 1, "resumed_at": now + timedelta(seconds=5)}]
        assert run(ctl, [fail2])["auto_paused"] == 0
        # a failure AFTER the resume → re-pause with the doubled backoff
        ctl[0]["resumed_at"] = now - timedelta(minutes=5)
        r = run(ctl, [fail2])
        assert r["auto_paused"] == 1 and any("paused for 120 min" in str(p) for _, p in writes), writes
        # an operator's pause is left alone
        man = [{"feed_id": "coolbet_prematch", "paused": True, "paused_by": "owner",
                "auto_pause_count": 0, "resumed_at": None}]
        assert run(man, [fail2])["auto_paused"] == 0 and not writes
        # success after an auto-pause resets the counter
        ok = dict(fail2, fail_streak=0, last_run_status="completed", status="ok")
        r = run([{"feed_id": "coolbet_prematch", "paused": False, "paused_by": None,
                  "auto_pause_count": 2, "resumed_at": now}], [ok])
        assert r["auto_reset"] == 1
    finally:
        fc.execute_query, fc.execute_write, fc._notify = orig_q, orig_w, orig_n

    from workers.registry.feed_registry import FEEDS_BY_ID
    for fid in ("coolbet_prematch", "epicbet_prematch", "unibet_prematch", "tonybet_prematch"):
        assert FEEDS_BY_ID[fid].get("auto_pause"), f"{fid} lost auto_pause"
    import pathlib
    assert (pathlib.Path(__file__).parent.parent / "supabase/migrations/391_feed_auto_pause.sql").exists()

@test("COOLBET-SEARCH-BUDGET — the fallback search cannot recreate the footprint that got the exit IP flagged")
def test_coolbet_search_budget():
    """#108 / #091 (2026-09-23). With fo-category retired, every fixture fell back to up
    to 5 search requests: 6,033 searches in 8 h from one IP (peak 1,517 Coolbet
    requests/hour) before Imperva flagged the zone.ee exit. The sweep now searches
    only fixtures kicking off within the horizon, and at most the budget per sweep;
    a skipped fixture is UNRESOLVED, never recorded as absent."""
    import inspect
    from workers.automation import coolbet_explorer as ce
    assert ce._SEARCH_FIXTURE_BUDGET <= 60, "search budget raised past the safe footprint"
    assert ce._SEARCH_HORIZON_H <= 24
    src = inspect.getsource(ce.run_bulk)
    assert "searches_used >= _SEARCH_FIXTURE_BUDGET" in src and "_SEARCH_HORIZON_H" in src
    assert "unreachable = True" in src, "a budget-skipped fixture must count as unresolved, not absent"
    assert src.index("searches_used >= _SEARCH_FIXTURE_BUDGET") < src.index("search_coolbet_event("), (
        "the budget check must run BEFORE the search request")


@test("UNIBET-TAB-NOT-LOADED — the Unibet sweep reloads a tab that is not really on unibet.ee, and names status 0")
def test_unibet_tab_not_loaded():
    """2026-09-25: Unibet-Site was dark 00:09-08:23 UTC (5 failed runs, auto-paused). After a Chrome
    restart at 00:18 the CDP tab was LISTED as unibet.ee but its document was about:blank, so every
    injected fetch failed with status 0 and the sweep reported "session blocked?". Fix: check the
    document origin before sweeping and Page.navigate to unibet.ee once if it is wrong; keep the HTTP
    status so the reason says "status 0: no answer" vs "blocked"."""
    # read the file, not inspect.getsource: other Unibet tests reload the module concurrently
    full = _engine_path("workers/automation/unibet_odds_feed.py").read_text(encoding="utf-8")
    src = full[full.index("async def _async_run_bulk("):full.index("\ndef run_bulk(")]
    i = src.index('origin = await _eval("location.origin"')
    assert i < src.index("qb = await inj("), "the origin check must run before the first API fetch"
    assert '"method": "Page.navigate"' in src and 'origin.endswith("unibet.ee")' in src
    assert 'c["last_status"] = d.get("s")' in src and "tab not on unibet.ee" in src
    assert "reuse any page tab" in src, "no unibet.ee tab at all must also self-heal, not fail the run"


@test("FOOTPRINT-HOUR-BOOKING — a request batch is booked under the hour it was counted; 'budget spent' only at the budget")
def test_footprint_hour_booking():
    """2026-09-24 (#139 Feeds review): Tonybet refusals made at 18:59:57 at 150/150 were flushed after
    the hour turned and booked under 19:00 (81/150), so /admin/feeds said "request budget spent" in an
    hour nowhere near its budget. Now the batch keeps the hour it was counted in and is flushed the
    moment the hour changes; feed_health only says "budget spent" when requests >= budget."""
    import workers.utils.footprint as f
    import workers.jobs.feed_health as fh
    import workers.api_clients.db as db
    from datetime import datetime, timezone
    calls = []
    orig_w, orig_h = db.execute_write, f._hour
    h18 = datetime(2026, 9, 24, 18, tzinfo=timezone.utc)
    h19 = datetime(2026, 9, 24, 19, tzinfo=timezone.utc)
    with _PUBLISHER_PATCH_LOCK:  # footprint module state is process-global
        try:
            db.execute_write = _this_thread_only(lambda sql, p=None: calls.append(p), orig_w)
            f._WRITES_ENABLED = True   # harness default is off (FOOTPRINT-SMOKE-NO-PROD-WRITES)
            f.flush()
            calls.clear()
            f._hour = lambda: h18
            f.record("SmokeBook")
            f._hour = lambda: h19
            f.record("SmokeBook")
            f.flush()
        finally:
            db.execute_write, f._hour = orig_w, orig_h
            f._WRITES_ENABLED = False
    booked = [(c[0], c[1].hour) for c in calls if c and c[0] == "SmokeBook"]
    assert booked == [("SmokeBook", 18), ("SmokeBook", 19)], booked
    under = fh.footprint_warnings({"requests_1h": 73, "budget_1h": 150, "refused_1h": 4, "challenges_1h": 0})
    assert under and "budget spent" not in under[0] and "under budget" in under[0], under
    at = fh.footprint_warnings({"requests_1h": 150, "budget_1h": 150, "refused_1h": 4, "challenges_1h": 0})
    assert at and "budget spent" in at[0], at


@test("FOOTPRINT-PRIORITY-RESERVE — deferrable requests stop before the cap; every refusal names its process")
def test_footprint_priority_reserve():
    """#151 (2026-09-25). Friday's weekend slate held BOTH books at their hourly budget 10:00-15:00
    UTC: Tonybet deep boards (~120/h) starved live stats (2 requests in the 14:00 hour, not 30) and
    the 14:20 results run; the Coolbet sweep's refresh of far-off fixtures got the near-kickoff close
    refused at 14:53/14:59. Deferrable callers now ask has_headroom() and keep a per-book reserve for
    the requests that cannot wait. Separately, a stray refusal under budget had no log line anywhere
    on the VPS, so each refusal now records host/proc/pid into book_footprint.refused_by (mig 445)."""
    import inspect
    from pathlib import Path
    from datetime import datetime, timedelta, timezone
    import workers.utils.footprint as f
    import workers.jobs.feed_health as fh
    import workers.api_clients.db as db
    from workers.automation import tonybet_feed, coolbet_explorer as ce
    from workers.jobs import near_kickoff_capture as nk

    calls = []
    with _PUBLISHER_PATCH_LOCK:  # footprint module state is process-global
        saved = (f._db_count, db.execute_write, f._refused_by_col)
        try:
            f.flush()
            f._pending.clear(); f._refusers.clear()
            # 1. reserve thresholds: Tonybet keeps 40% of 250, Coolbet a fifth of 500
            assert f.budget("Tonybet") == 250
            f._db_count = lambda book: 149
            assert f.has_headroom("Tonybet")
            f._db_count = lambda book: 150
            assert not f.has_headroom("Tonybet")
            f._db_count = lambda book: 399
            assert f.has_headroom("Coolbet")
            f._db_count = lambda book: 400
            assert not f.has_headroom("Coolbet")
            assert f.has_headroom("NoSuchBook")
            assert not f._pending["Tonybet"]["refused"], "a deferral must never be booked as a refusal"
            # 2. a refusal records who refused, and flush writes it
            f._db_count = lambda book: f.budget(book)
            db.execute_write = _this_thread_only(lambda sql, p=None: calls.append((sql, p)), saved[1])
            f._WRITES_ENABLED = True   # harness default is off (FOOTPRINT-SMOKE-NO-PROD-WRITES)
            try:
                f.check("Coolbet")
                raise AssertionError("check() did not refuse at the budget")
            except f.FootprintBudgetExceeded:
                pass
            f.flush()
            rows = [p for sql, p in calls if p and p[0] == "Coolbet"]
            assert rows and "refused_by" in calls[-1][0] and rows[-1][7] and "/" in rows[-1][7][0], calls
            # 3. before migration 445 is applied, counting continues without the column
            calls.clear()
            def _no_col(sql, p=None):
                if "refused_by" in sql:
                    raise RuntimeError('column "refused_by" of relation "book_footprint" does not exist')
                calls.append((sql, p))
            db.execute_write = _this_thread_only(_no_col, saved[1])
            f._refused_by_col = True
            f.record("SmokeBook")
            f.flush()
            assert calls and calls[-1][1][0] == "SmokeBook" and len(calls[-1][1]) == 7, calls
        finally:
            f._db_count, db.execute_write, f._refused_by_col = saved
            f._pending.clear(); f._refusers.clear()
            f._WRITES_ENABLED = False

    # 4. the deferrable callers are gated; the must-run ones are not
    bulk = inspect.getsource(tonybet_feed.run_bulk)
    assert "footprint.has_headroom(BOOKMAKER)" in bulk and "deep_deferred" in bulk
    assert "has_headroom" not in inspect.getsource(nk), "the near-kickoff close is what the reserve is FOR"
    for fn in (tonybet_feed.run_live, tonybet_feed.run_results):
        assert "has_headroom" not in inspect.getsource(fn)
    sweep = inspect.getsource(ce.run_board_sweep)
    assert 'footprint.has_headroom("Coolbet")' in sweep and "_within_every_pass_tier" in sweep
    now = datetime(2026, 9, 25, 12, tzinfo=timezone.utc)
    assert ce._within_every_pass_tier(now + timedelta(hours=2), now)
    assert not ce._within_every_pass_tier(now + timedelta(hours=20), now)
    sched = (Path(__file__).resolve().parent.parent / "workers/scheduler.py").read_text()
    job = sched[sched.index("def job_coolbet_odds_snapshot"):sched.index("def _coolbet_odds_snapshot_wrapper")]
    assert "reserve_deferred" in job, (
        "a pass that deferred for the reserve must not count as 'stored 0 rows for N due fixtures'")

    # 5. the Feeds warning names the refuser
    w = fh.footprint_warnings({"requests_1h": 39, "budget_1h": 500, "refused_1h": 1,
                               "challenges_1h": 0, "refused_by": ["mac/foo.py/123"]})
    assert w and "by mac/foo.py/123" in w[0], w
    mig = Path(__file__).resolve().parent.parent / "supabase/migrations/445_book_footprint_refused_by.sql"
    assert "ADD COLUMN IF NOT EXISTS refused_by text[]" in mig.read_text()


@test("BOOK-FOOTPRINT — every book request is metered, capped per hour, and warned on before a block")
def test_book_footprint():
    """#110 (2026-09-23). #108's Imperva flag followed ~7,500 Coolbet requests in 8 h that
    nothing counted. Every outbound request to a scraped book now goes through
    workers/utils/footprint.py: a per-book hourly budget (refused, not sent, when spent),
    outcome counts (bot-check / error / slow) in book_footprint, and a warn on the book's
    /admin/feeds block at 80% of budget or a rising bot-check share."""
    import inspect
    from pathlib import Path
    from workers.utils import footprint as fp
    from workers.jobs import feed_health as fh
    from workers.automation import coolbet_session, epicbet_explorer, tonybet_feed, unibet_odds_feed
    from workers.jobs import inplay_epicbet_collector

    # 1. budgets exist for every scraped book and Coolbet's stays under the flagged volume
    for book in ("Coolbet", "Tonybet", "Unibet-Site", "Epicbet"):
        assert fp.budget(book), f"{book} has no request budget"
    assert fp.budget("Coolbet") < 750, "Coolbet budget at/above the volume that got the IP flagged"

    # 2. check() refuses at the cap without sending; fails open on a DB error
    saved = (fp._db_count, dict(fp._pending))
    try:
        fp._pending.clear()
        fp._db_count = lambda book: fp.budget(book)
        import logging as _lg
        _seen = []
        _h = _lg.Handler(); _h.emit = lambda r: _seen.append(r.getMessage())
        fp.log.addHandler(_h)
        try:
            fp.check("Coolbet")
            raise AssertionError("check() did not refuse at the budget")
        except fp.FootprintBudgetExceeded:
            pass
        finally:
            fp.log.removeHandler(_h)
        # a refusal must say which process refused and what it believed (2026-09-24)
        assert any("footprint REFUSED Coolbet" in m and "pid=" in m for m in _seen), _seen
        fp._db_count = lambda book: 0
        fp.check("Coolbet")
    finally:
        fp._db_count = saved[0]
        fp._pending.clear()
    assert fp.classify_status(403) == "challenge" and fp.classify_status(503) == "error"
    assert fp.classify_status(200) == "ok" and fp.classify_status(None) == "error"

    # 3. every transport is metered
    assert "metered_session(\"Tonybet\")" in inspect.getsource(tonybet_feed._session)
    assert "metered_session(\"Epicbet\")" in inspect.getsource(epicbet_explorer._session)
    assert "footprint.check(\"Epicbet\")" in inspect.getsource(epicbet_explorer._fs_get_json)
    assert "metered_session(\"Epicbet-inplay\")" in inspect.getsource(inplay_epicbet_collector), (
        "the in-play collector must meter on its own budget, never the pre-match sweep's")
    assert "footprint.check" in inspect.getsource(coolbet_session._fs_call)
    post_src = inspect.getsource(coolbet_session.CoolbetSession.post)
    assert "footprint.record" in post_src and "footprint.check" not in post_src, (
        "POST is the placement path: counted, never refused by the budget")
    assert "footprint.check" in inspect.getsource(coolbet_session.CoolbetSession.get), "direct GET unmetered"
    usrc = inspect.getsource(unibet_odds_feed)
    assert usrc.count("footprint.check(_BOOKMAKER)") >= 3, "a Unibet transport is unmetered"

    # 4. early warning
    assert fh.footprint_warnings({"requests_1h": 10, "budget_1h": 500, "challenges_1h": 0}) == []
    assert fh.footprint_warnings({"requests_1h": 450, "budget_1h": 500, "challenges_1h": 0})
    assert fh.footprint_warnings({"requests_1h": 100, "budget_1h": 500, "challenges_1h": 8})
    assert fh.footprint_warnings({"requests_1h": 500, "budget_1h": 500, "refused_1h": 3})

    # the harness must never book its fake refusals/errors into the production table (#151)
    assert fp._WRITES_ENABLED is False, "smoke harness left footprint writes on — CI would write to prod"
    mig = Path(__file__).resolve().parent.parent / "supabase/migrations/392_book_footprint.sql"
    assert "CREATE TABLE IF NOT EXISTS book_footprint" in mig.read_text()


@test("COOLBET-BOARD-SWEEP-DEFAULT — scheduled sweep uses the board, a failed listing never poisons the memo, Estonian names match")
def test_coolbet_board_sweep_default():
    """#091 / #110 step 2 (2026-09-23). Coverage diff from the Mac's IP, 48 h: board
    55 fixtures vs run_bulk 41 (1 only in run_bulk) for ~100 listing requests instead
    of thousands of searches. Three pins: (1) the job defaults to run_board_sweep with
    an env rollback; (2) a non-200 listing RAISES for the board sweep — returning []
    taught the near-term memo that every category was empty during the #108 block;
    (3) Coolbet lists national teams in Estonian, which the matcher now translates."""
    import inspect
    from pathlib import Path
    from workers.automation import coolbet_explorer as ce, coolbet_placer as cp
    from workers.automation.coolbet_matching import norm_team
    sched = (Path(__file__).resolve().parent.parent / "workers/scheduler.py").read_text()
    job = sched[sched.index("def job_coolbet_odds_snapshot"):sched.index("def _coolbet_odds_snapshot_wrapper")]
    assert 'os.getenv("COOLBET_SWEEP_MODE", "board")' in job and "run_board_sweep(" in job

    class _R:
        status_code = 403
    class _S:
        def get(self, *a, **k):
            return _R()
    assert cp.fetch_events_for_league(_S(), 1) == []
    try:
        cp.fetch_events_for_league(_S(), 1, raise_on_error=True)
        raise AssertionError("a failed listing must raise for the board sweep")
    except RuntimeError:
        pass
    assert "raise_on_error=True" in inspect.getsource(ce.run_board_sweep)

    for et, en in (("Holland", "Netherlands"), ("Saksamaa", "Germany"), ("Põhja-Iirimaa", "Northern Ireland"),
                   ("Prantsusmaa U21", "France U21"), ("Elevandiluurannik", "Ivory Coast")):
        assert norm_team(et) == norm_team(en), (et, norm_team(et), norm_team(en))
    assert norm_team("Rhode Island") == "rhode island", "whole-name only — clubs must not be rewritten"


