@test("BETFAIR-EXCHANGE-READER — London exit only, own table, liquidity recorded, read-only")
def test_betfair_exchange_reader():
    """#117 (2026-09-24). Exchange prices through the London Droplet (SOCKS :1082); the
    exchange serves no markets to the Finnish VPS. Pins: never the Estonian exit, never
    odds_snapshots (thin placeholders like 1.10/110 would poison every consensus), every
    quote carries back+lay+sizes+matched volume, and no login/order endpoints."""
    import inspect
    from pathlib import Path
    from workers.automation import betfair_exchange_feed as b
    from workers.utils import footprint
    src = inspect.getsource(b)
    assert b._PROXY.endswith(":1082") and ":1081" not in src
    assert "INSERT INTO exchange_quotes" in src and "INSERT INTO odds_snapshots" not in src
    assert "store_book_odds_snapshots" not in src, "exchange quotes never enter odds_snapshots"
    for bad in ("identitysso", "placeOrders", "/login"):
        assert bad not in src
    assert footprint.budget("Betfair-Exchange")
    assert b.is_liquid(2.48, 2.52, 18656) and not b.is_liquid(1.10, 110.0, 0.0)
    assert not b.is_liquid(2.08, 2.20, 30.7), "a €31 market with a 6% spread is not a price"
    assert b.split_event_name("Kosovo v Republic of Ireland") == ("Kosovo", "Republic of Ireland")
    assert b.runner_selection("MATCH_ODDS", "The Draw", "A", "B") == "draw"
    assert b.runner_selection("OVER_UNDER_25", "Over 2.5 Goals", "A", "B") == "over"
    # #119 D — extra markets: AH rows carry the HOME line on both sides (odds_snapshots convention)
    assert b.line_of("ASIAN_HANDICAP", "home", -1.25) == -1.25
    assert b.line_of("ASIAN_HANDICAP", "away", 1.25) == -1.25
    assert b.line_of("ALT_TOTAL_GOALS", "over", 2.75) == 2.75
    assert b.line_of("OVER_UNDER_25", "over", 0.0) == 2.5, "fixed O/U rows carry their line (join key vs odds_snapshots)"
    assert b.runner_selection("BOTH_TEAMS_TO_SCORE", "Yes", "A", "B") == "yes"
    assert b.runner_selection("ASIAN_HANDICAP", "B", "A", "B") == "away"
    assert b.EXTRA_MIN_MATCHED >= 1000, "extra markets only for events with a liquid match-odds market"
    assert "handicap_line" in (Path(__file__).resolve().parent.parent / "supabase/migrations/396_exchange_quotes_lines.sql").read_text()
    # retention: thin far-from-kickoff captures to hourly after 2 days, keep near-kickoff in full
    psrc = inspect.getsource(b.prune)
    assert b.RETAIN_FULL_WITHIN_MIN >= 180 and "date_trunc('hour', captured_at)" in psrc
    assert "minutes_to_kickoff > %s" in psrc and "rn > 1" in psrc
    assert 'id="exchange_quotes_prune"' in (Path(__file__).resolve().parent.parent / "workers/scheduler.py").read_text()
    root = Path(__file__).resolve().parent.parent
    assert "CREATE TABLE IF NOT EXISTS exchange_quotes" in (root / "supabase/migrations/395_exchange_quotes.sql").read_text()
    assert 'id="betfair_exchange_snapshot"' in (root / "workers/scheduler.py").read_text()


@test("SHARP-TIER — Pinnacle + Betfair Exchange: blend when they agree, CONFLICT when they don't, off by default")
def test_sharp_tier():
    """#119 step A/B (2026-09-24). Two independent sharp prices. A disagreement is the
    phantom-edge detector (stale AF-Pinnacle / placeholder line) and must never be
    silently replaced by a softer anchor. OFF by default until the #117 study."""
    import inspect
    from datetime import datetime, timedelta, timezone
    from workers.utils import anchor as A
    S = ("home", "draw", "away")
    now = datetime(2026, 9, 24, 12, 0, tzinfo=timezone.utc)
    f = now - timedelta(minutes=5)
    liquid = {"home": {"back": 2.48, "lay": 2.52, "market_matched": 18656},
              "draw": {"back": 3.30, "lay": 3.35, "market_matched": 18656},
              "away": {"back": 3.35, "lay": 3.40, "market_matched": 18656}}
    probs, liq, _ = A.exchange_fair(liquid, S)
    assert liq and abs(sum(probs.values()) - 1) < 1e-9
    placeholder = {s: {"back": 1.10, "lay": 110.0, "market_matched": 0} for s in S}
    assert A.exchange_fair(placeholder, S)[1] is False
    ex = {"probs": probs, "liquid": True, "ts": f}
    pin_ok = ([2.45, 3.30, 3.30], f)                    # tight, near the exchange
    assert A.compute_sharp(pin_ok, ex, S, at=now).source == "sharp_blend"
    a = A.compute_sharp(([1.97, 3.62, 4.35], f), ex, S, at=now)   # tight but far away
    assert a.source == "sharp_conflict" and not a.probs, "a conflict carries NO probabilities"
    assert A.compute_sharp(None, ex, S, at=now).source == "exchange_liquid"
    assert A.compute_sharp(pin_ok, None, S, at=now).source == "pinnacle_tight"
    stale_ex = dict(ex, ts=now - timedelta(minutes=45))
    assert A.compute_sharp(None, stale_ex, S, at=now).source == "none"
    assert A.compute_sharp(None, dict(ex, liquid=False), S, at=now).source == "none"
    src = inspect.getsource(A.resolve_anchor)
    assert 'os.getenv("ANCHOR_USE_EXCHANGE", "0") == "1"' in src, "sharp tier must be OFF by default"


