@test("RESULTS-TIEBREAK — a third read (AF re-fetch + ESPN) decides AF-vs-Tonybet; majority rewrites + re-grades")
def test_results_tiebreak():
    """#121 6b (owner chose C, 2026-09-24). Two sources cannot out-vote each other. The AF
    re-fetch is a vote (ESPN covers ~25 top leagues; both real disagreements were lower-tier),
    the STORED AF score is not (it is what is being judged). JOS Watergraafsmeer v TEC: AF
    stored 4-4, Tonybet 2-2, AF re-fetch 2-2 -> corrected to 2-2 on first run."""
    import inspect
    from workers.jobs import results_check as rc
    v = rc.verdict
    assert v((2, 2), (2, 2), None) == ("corrected", (2, 2)), "AF corrected itself"
    assert v((4, 4), (2, 2), (2, 2)) == ("corrected", (2, 2)), "ESPN + Tonybet out-vote AF"
    assert v((4, 4), (2, 2), (4, 4)) == ("af_confirmed", None), "ESPN backs AF: nothing changes"
    assert v((4, 4), (2, 2), None) == ("unresolved", None) and v(None, (2, 2), None)[0] == "unresolved"
    src = inspect.getsource(rc._regrade) + rc._REGRADE_SQL
    assert "LEFT(b.void_reason, 10) <> 'quarantine'" in src, "quarantined voids are never resurrected"
    assert '("skip", b["result"])' in src, "only rewrite when the grade changes"
    assert "current_bankroll" in src and "settle_picks_forward_test([mid])" in src
    assert "execute_write_returning" in src, "reopen must COMMIT (execute_query does not)"
    run = inspect.getsource(rc.run)
    assert 'record_finding("results_corrected"' in run and '"af_confirmed" in seen' in run


@test("PICKS-OUTLIER-ANCHOR-PUBLISHABLE — the PICKS outlier anchor uses every real book; OWN keeps the Estonian set (#129)")
def test_picks_outlier_anchor_publishable():
    """#129 (2026-09-24): #005 widened the PICKS price basis to is_publishable_book() but the
    ODDS-OUTLIER-FILTER anchor still read PRICE_REFERENCE_BOOKMAKERS (4 Estonian books +
    Pinnacle), so a fixture without Pinnacle and with <3 of those four had no anchor and every
    candidate was rejected — v10 fell from ~23 picks/wk to 3. OWN must stay on its own set."""
    import inspect
    from workers.jobs import daily_pipeline_v2 as dp
    load = inspect.getsource(dp._load_today_from_db)
    block = load[:load.index("outlier_offers[mid][key].append")]
    block = block[block.rindex("for row in odds_raw:"):]
    assert "if not is_publishable_book(bookmaker):" in block
    assert "bookmaker not in PRICE_REFERENCE_BOOKMAKERS" not in block, "anchor must not read the Estonian set"
    assert dp.is_publishable_book("1xBet") and dp.is_publishable_book("Pinnacle")
    assert not dp.is_publishable_book("Unibet-Kambi") and not dp.is_publishable_book("Max")
    # 🤖 OWN is unchanged. (#162 W7.2 (2026-09-26): the pipeline shadow passes that also filtered on
    # ACCESSIBLE_BOOKMAKERS are deleted — every bot they served was retired.)
    # …and OWN bots fed from simulated_bets re-apply the pre-#129 Estonian anchor,
    # because #129 lets thinner fixtures into that table:
    import workers.automation.pick_generator as pg
    assert "_own_outlier_ok(" in inspect.getsource(pg.generate)
    ok, why = pg._own_outlier_ok("00000000-0000-0000-0000-000000000000", "1x2", "home", 2.0)
    assert (ok, why) == (False, "no_own_anchor"), "no Estonian anchor must reject for OWN"
    assert pg._own_outlier_ok("x", "over_under_25", "over", 2.0) == (True, "")
    # one price source under two names counts once toward the >= 3-book anchor
    assert 'bookmaker == "Marathonbet" and any(b == "1xBet"' in load


@test("OBS-LOG-ALL-JOBS — no job runs its work outside _run_job; a crash is a FAILED pipeline_runs row (#034)")
def test_obs_log_all_jobs():
    """#034 (2026-09-24): 20 jobs ran their body OUTSIDE _run_job and then called
    `_run_job(name, lambda: None)` — a crash left NO pipeline_runs row, a success logged a
    no-op, and a feed pause from /admin/feeds could not stop them. All converted to
    `_run_job(name, _job_<name>_impl)`. Pins zero call sites (not a count) + the behaviour."""
    import re as _re, sys as _sys, types as _types, importlib as _il
    src = _engine_path("workers/scheduler.py").read_text()
    live = _re.findall(r"^\s*_run_job\([^\n]*lambda: None\)", src, _re.M)
    assert not live, f"the no-op-lambda pattern is back: {live}"

    if "apscheduler" not in _sys.modules:
        try:
            import apscheduler  # noqa: F401
        except ImportError:   # local dev without the scheduler deps: stub the imports only
            for m in ("apscheduler", "apscheduler.schedulers", "apscheduler.schedulers.background",
                      "apscheduler.executors", "apscheduler.executors.pool",
                      "apscheduler.triggers", "apscheduler.triggers.cron", "apscheduler.triggers.interval"):
                _sys.modules.setdefault(m, _types.ModuleType(m))
            _sys.modules["apscheduler.schedulers.background"].BackgroundScheduler = object
            _sys.modules["apscheduler.executors.pool"].ThreadPoolExecutor = object
            _sys.modules["apscheduler.triggers.cron"].CronTrigger = object
            _sys.modules["apscheduler.triggers.interval"].IntervalTrigger = object
    sched = _il.import_module("workers.scheduler")
    import workers.utils.pipeline_utils as pu
    import workers.jobs.feed_control as fc
    calls = []
    saved = (pu.log_pipeline_start, pu.log_pipeline_complete, pu.log_pipeline_failed,
             fc.is_job_paused, sched._kuma_push, sched._job_coolbet_price_sanity_impl)
    try:
        pu.log_pipeline_start = lambda name, d: calls.append(("start", name)) or 1
        pu.log_pipeline_complete = lambda rid: calls.append(("completed",))
        pu.log_pipeline_failed = lambda rid, msg: calls.append(("failed", msg))
        fc.is_job_paused = lambda name: False
        sched._kuma_push = lambda *a, **k: None
        def _boom():
            raise RuntimeError("deliberate")
        sched._job_coolbet_price_sanity_impl = _boom
        sched.job_coolbet_price_sanity()          # must NOT raise out of the job
        assert ("start", "coolbet_price_sanity") in calls and ("failed", "deliberate") in calls, calls
        calls.clear()
        sched._job_coolbet_price_sanity_impl = lambda: None
        sched.job_coolbet_price_sanity()
        assert ("completed",) in calls, calls
    finally:
        (pu.log_pipeline_start, pu.log_pipeline_complete, pu.log_pipeline_failed,
         fc.is_job_paused, sched._kuma_push, sched._job_coolbet_price_sanity_impl) = saved


