@test("MATCHER-ORIENTATION-STRICT — a book listing our teams reversed is refused, never stored mirrored (#001)")
def test_matcher_orientation_strict():
    """#001 (2026-09-24): match_event_to_af (main Coolbet board sweep, Betfair exchange,
    Odds API fallback), fuzzy_match_event (Epicbet / Unibet-Site / Tonybet / placer) and the
    league-sweep matcher all took max(direct, swapped) or an order-blind token_sort_ratio, so
    a reversed listing was accepted and every side-mapper wrote the book's "1" as our home.
    Now only the direct orientation matches. A shared token ("Tallinn") must not let a
    reversed listing through on its direct score (81.8 before the candidate-drop rule)."""
    import inspect
    from datetime import datetime, timezone
    from workers.automation import coolbet_matching as cm, coolbet_placer as cp, coolbet_explorer as ce
    ko = datetime(2026, 9, 24, 18, tzinfo=timezone.utc)
    af = [{"id": 1, "ko": ko, "home": "Flora Tallinn", "away": "Levadia Tallinn", "country": "Estonia"}]
    assert cm.match_event_to_af("Flora Tallinn", "Levadia Tallinn", "ee", ko, af)[0] is not None
    assert cm.match_event_to_af("Levadia Tallinn", "Flora Tallinn", "ee", ko, af)[0] is None
    assert cm.match_event_to_af("Stoke", "Hull", "gb", ko,
        [{"id": 3, "ko": ko, "home": "Stoke City", "away": "Hull City", "country": "England"}])[0] is not None
    evs = [{"home": "Maccabi Tel Aviv", "away": "Maccabi Netanya", "start": ko.isoformat()}]
    assert cp.fuzzy_match_event("Maccabi Netanya", "Maccabi Tel Aviv", evs, ko) is None
    hit = cp.fuzzy_match_event("Maccabi Tel Aviv", "Maccabi Netanya", evs, ko)
    assert hit is not None and hit.get("_match_score") == 100, "score exposed for book_event_map"
    # review 2026-09-24: a refused reversed listing must still COMPETE — otherwise a decoy
    # with similar names wins ("Penarol v Nacional" -> "Penarol Rivera v Nacional Potosi").
    # Ties at 100 (subset names) are broken on exact name similarity.
    evs2 = [{"home": "Nacional", "away": "Penarol", "start": ko.isoformat()},
            {"home": "Penarol Rivera", "away": "Nacional Potosi", "start": ko.isoformat()}]
    af2 = [{"id": 1, "ko": ko, "home": "Nacional", "away": "Penarol", "country": "Uruguay"},
           {"id": 2, "ko": ko, "home": "Penarol Rivera", "away": "Nacional Potosi", "country": "Uruguay"}]
    assert cp.fuzzy_match_event("Penarol", "Nacional", evs2, ko) is None
    assert cm.match_event_to_af("Penarol", "Nacional", "uy", ko, af2)[0] is None
    assert cp.fuzzy_match_event("Nacional", "Penarol", evs2, ko)["home"] == "Nacional"
    assert cm.match_event_to_af("Nacional", "Penarol", "uy", ko, af2)[0]["id"] == 1
    assert cm.match_event_to_af("Penarol Rivera", "Nacional Potosi", "uy", ko, af2)[0]["id"] == 2
    af3 = [{"id": 1, "ko": ko, "home": "Flora Tallinn", "away": "FCI Levadia", "country": "Estonia"},
           {"id": 2, "ko": ko, "home": "Levadia B", "away": "Flora B", "country": "Estonia"}]
    assert (cm.match_event_to_af("Flora", "Levadia", "ee", ko, af3)[0] or {}).get("id") == 1, \
        "a reversed B-team listing must not block the senior match"
    src = inspect.getsource(ce)
    assert "fuzz.token_sort_ratio(af_key, cb_key)" not in src
    assert "if _swapped > _direct:" in src
    for f in ("unibet_odds_feed", "epicbet_explorer", "tonybet_feed"):
        mod = __import__(f"workers.automation.{f}", fromlist=["x"])
        assert 'ev.get("_match_score")' in inspect.getsource(mod), f"{f} must store the match score"


@test("BOOK-FEED-TIDYUPS — aliases, Unibet World routing, esoccer excluded, records_count, empty near-KO boards logged (#112)")
def test_book_feed_tidyups():
    """#112 (2026-09-24). (a) renamed / FIFA-named clubs the fuzzy scorer cannot bridge;
    (b) AF country='World' fixtures were 100% unmapped at Unibet (league_mapped 0, 121
    unmapped per sweep) — routed to Unibet's three international categories; 'esoccer'
    (console football) can never be a category; (c) _run_job records a sweep's `stored` as
    pipeline_runs.records_count (NULL for every _run_job row before); (d) a Tonybet event
    answering with an empty board near kickoff is now logged, not just counted."""
    import inspect
    from datetime import datetime, timezone
    from workers.automation import coolbet_placer as cp, unibet_odds_feed as uf
    from workers.jobs import near_kickoff_capture as nk
    ko = datetime(2026, 9, 24, 18, tzinfo=timezone.utc)
    for ours, theirs in ((("York United", "Pacific FC"), ("Inter Toronto", "Pacific FC")),
                         (("South Korea", "Japan"), ("Korea Republic", "Japan")),
                         (("Hapoel Nazareth Illit", "Hapoel Afula"), ("Hapoel Nof Hagalil", "Hapoel Afula"))):
        ev = cp.fuzzy_match_event(ours[0], ours[1],
                                  [{"home": theirs[0], "away": theirs[1], "start": ko.isoformat()}], ko)
