@test("ADMIN-SHARED-SHELL — one admin layout renders the sidebar and checks superadmin; no page brings its own shell")
def test_admin_shared_shell():
    """2026-09-24, owner: "the left navigation menu, when I navigate to other pages, loses the
    navigation menu … the left menu should be a single component and we should only render the
    middle block." The sidebar used to live in admin/bots/admin-shell.tsx and wrapped /admin/bots
    only. Now src/app/(app)/admin/layout.tsx checks superadmin ONCE (dev fixture bypass only) and
    renders the shared shell; the public Nav steps aside for /admin (public-chrome.tsx); pages
    keep their own superadmin check (defence in depth) but never import a shell or sidebar."""
    admin = _web_root / "src/app/(app)/admin"
    layout = admin / "layout.tsx"
    if not (_web_root / "src").exists():
        return
    assert layout.exists(), "admin/layout.tsx must exist — the one place the sidebar is rendered"
    src = layout.read_text(encoding="utf-8")
    assert 'from "@/components/admin/admin-shell"' in src and "<AdminShell" in src
    assert "requireSuperadmin()" in src and "if (!isBotBoardDevPreview())" in src
    shell = _web_path("src/components/admin/admin-shell.tsx").read_text(encoding="utf-8")
    assert "<AdminSidebar" in shell
    sidebar = _web_path("src/components/admin/admin-sidebar.tsx").read_text(encoding="utf-8")
    assert "usePathname" in sidebar and "ADMIN_NAV" in sidebar
    nav = _web_path("src/components/admin/admin-nav.ts").read_text(encoding="utf-8")
    pages = sorted(admin.rglob("page.tsx"))
    for p in pages:
        rel = p.parent.relative_to(admin).as_posix()
        route = "/admin" if rel == "." else f"/admin/{rel}"
        if "[" in route:
            continue
        body = p.read_text(encoding="utf-8")
        # #162 W6.8 (2026-09-26): a RETIRED page that only redirects (/admin/real-bets →
        # /admin/bots?section=money) keeps its URL but has no sidebar entry, and needs no gate of
        # its own — the target re-checks superadmin, like the /admin/shadow-bots/[bot] redirect.
        if "RETIRED" in body and "redirect(" in body and "createServerServiceClient" not in body:
            continue
        assert f'href: "{route}"' in nav, f"{route} has no sidebar entry in admin-nav.ts"
        assert "admin-shell" not in body and "AdminShell" not in body and "AdminSidebar" not in body, p
        # requireSuperadmin() (lib/admin-auth.ts) is the shared is_superadmin check (#162 W7.4)
        assert "is_superadmin" in body or "requireSuperadmin()" in body, f"{p} must keep its own server-side superadmin check"
    assert not (admin / "bots/admin-shell.tsx").exists(), "the per-page shell must stay deleted"
    chrome = _web_path("src/components/public-chrome.tsx").read_text(encoding="utf-8")
    assert 'pathname.startsWith("/admin/")' in chrome
    app_layout = (_web_root / "src/app/(app)/layout.tsx").read_text(encoding="utf-8")
    assert "<PublicChrome" in app_layout


@test("FOOTPRINT-PAUSE-NOT-A-MONEY-GATE — the Coolbet footprint pause stops sweeping, never real bets, and every surface says so")
def test_footprint_pause_not_a_money_gate():
    """#139 (owner decision 2026-09-24, "only sweeping stops"). `daemons_paused` stops the Coolbet
    odds sweeps, the feed watchdog and the paper Mac daemon. The real-money placers pass through
    placement_gate.assert_run_may_place(), which reads placement_paused + real_money_armed + money_gate_ready (migration 436), never daemons_paused.
    coolbet_control's readiness used to list the footprint pause as a BLOCKER, so the daily Telegram
    summary said BLOCKED on a pause that would not have stopped a real bet. Now: the gate ignores it
    (on purpose), readiness reports it as a warning, and the /admin/bots ladder shows it as an
    information-only layer that can never block CAN STAKE."""
    import inspect
    from datetime import datetime, timezone, timedelta
    from workers.automation import placement_gate as pg
    from workers.automation import coolbet_control as cc
    gate_src = inspect.getsource(pg.assert_run_may_place)
    assert "daemons" not in gate_src, "owner decision: the footprint pause is NOT a real-money gate"
    now = datetime(2026, 9, 24, 12, 0, tzinfo=timezone.utc)
    st = {"placement_paused": False, "real_money_armed": True, "money_gate_ready": True, "daemons_paused": True,
          "daemons_paused_reason": "imperva", "last_ui_attempt_at": now - timedelta(minutes=5)}
    r = cc._evaluate_readiness(st, [{"bot_name": "b", "ui_place_enabled": True}], now)
    assert r["can_place_now"] is True and not any("daemon" in b.lower() for b in r["blockers"]), r
    assert any("does NOT stop real bets" in w for w in r["warnings"]), r["warnings"]
    ladder = _web_root / "src/lib/bot-controls/ladder.ts"
    if not ladder.exists():
        return
    src = ladder.read_text(encoding="utf-8")
    i = src.index('key: "footprint"')
    block = src[i:src.index("});", i)]
    assert 'state: "info"' in block and '"blocked"' not in block and '"unknown"' not in block, (
        "the footprint layer must be information only — it may never block or un-know CAN STAKE")
    assert "does not stop real bets" in block


