@test("UNIFIED-BOT-VIEWS-CONTRACT — bot_ledger / bot_scoreboard / bot_capabilities / bot_config match the #139 contract")
def test_unified_bot_views_contract():
    """#139 UNIFIED-BOT-MODEL phase 1 (2026-09-24). Migration 410 builds one ledger over
    simulated_bets / shadow_bets / picks_forward_test, one scoreboard, one capability view
    and the bot_config table, per docs/UNIFIED_BOT_MODEL_DESIGN_2026_09_24.md § "Data
    contract — phase 1". Pins: every contract column/view exists; admin-only (service_role,
    never anon — #072); the ledger rules (no combos; one ledger per bot — sim-writing bots add
    no shadow rows, every other bot keeps all cohorts deduped earliest-first; junk_anchor ->
    control_junk_anchor); and the exporter resolves every ACTIVE
    bot to a contract family with {name, value, source} gates, scheduled daily 03:40."""
    import re as _re
    sql = _engine_path("supabase/migrations/410_unified_bot_views.sql").read_text()
    low = sql.lower()
    assert "create table if not exists public.bot_config" in low
    for v in ("bot_ledger", "bot_scoreboard", "bot_capabilities"):
        assert f"create or replace view public.{v} as" in low, v
    seg = lambda a, b: low[low.index(a):low.index(b)]
    cfg = seg("create table if not exists public.bot_config", "comment on table public.bot_config")
    for col in ("bot_name", "family", "description", "ledger", "writer_job", "cadence", "markets",
                "prob_source", "edge_floor", "edge_floor_source", "odds_min", "odds_max", "gates",
                "books", "books_source", "anchor", "placeable", "published", "telegram",
                "admissible_metric", "exported_at"):
        assert _re.search(rf"\n\s+{col}\s", cfg), f"bot_config.{col}"
    assert _re.search(r"bot_name\s+text primary key", cfg) and _re.search(r"gates\s+jsonb", cfg)
    assert _re.search(r"books\s+text\[\]", cfg) and _re.search(r"markets\s+text\[\]", cfg)
    led = seg("create or replace view public.bot_ledger", "comment on view public.bot_ledger")
    for col in ("source", "pick_id", "bot_name", "bot_id", "match_id", "kickoff", "pick_time",
                "market", "selection", "odds", "bookmaker", "result", "pnl_unit", "clv_raw",
                "clv_mc", "clv_pinnacle", "is_inplay", "model_version", "rule_version"):
        assert _re.search(rf"\bas {col}\b", led), f"bot_ledger.{col}"
    assert "combo_legs is null" in led
    # ONE LEDGER PER BOT (ANALYSIS_GOTCHAS §18): sim-writing bots contribute no shadow rows;
    # every other bot keeps ALL its shadow rows incl. HHMM cohorts (their only record — an
    # HHMM exclusion lost 11,447 picks across 37 bots).
    assert "shadow_cohort !~" not in led, "HHMM timing cohorts must not be excluded"
    assert "not exists (select 1 from simulated_bets s2 where s2.bot_id = x.bot_id)" in led
    assert "distinct on (x.bot_id, x.match_id, x.market, x.selection)" in led and "x.pick_time" in led
    assert "s.xg_source is not null" in led, "in-play sim rows are flagged by xg_source too"
    assert "'control_junk_anchor'" in led and "'junk_anchor'" in led
    for n in ("bot_sharp_1x2_v1", "bot_sharp_ou_v1", "bot_consensus_b_v1", "bot_consensus_c_v1", "bot_consensus_d_v1"):
        assert f"'{n}'" in led, n
    assert "clv_margin_corrected" in led and "clv_pinnacle_devig" in led
    sb = seg("create or replace view public.bot_scoreboard", "comment on view public.bot_scoreboard")
    for col in ("bot_name", "display_name", "source", "is_active", "retired_at", "maturity_label",
                "family", "picks_total", "pending", "settled", "won", "lost", "void", "roi_unit",
                "clv_mc_n", "clv_mc_mean", "clv_mc_se", "clv_mc_t", "clv_pin_n", "clv_pin_mean",
                "clv_pin_t", "first_pick_at", "last_pick_at", "picks_7d", "settled_7d",
                "clv_pin_se", "clv_outlier_n", "scored_rule_version", "earlier_version_picks"):
        assert _re.search(rf"\b{col}\b", sb), f"bot_scoreboard.{col}"
    # pre-registration: forward-test bots scored on their CURRENT rule_version only (mig 346)
    assert "l.rule_version = c.rule_version" in sb, "forward-test rule versions must never be pooled"
    cap = seg("create or replace view public.bot_capabilities", "comment on view public.bot_capabilities")
    for col in ("bot_name", "collect", "publish", "telegram", "place_capable", "place_enabled",
                "fleet_placement_paused", "fleet_real_money_armed", "writing_7d"):
        assert _re.search(rf"\b{col}\b", cap), f"bot_capabilities.{col}"
    # retired bots keep writing on purpose (owner 05-20 / 09-18): shown, never hidden
    assert "as writing_7d" in cap and "interval '7 days'" in cap
    assert "coolbet_placer_bots" in cap and "coolbet_session_state" in cap
    # admin only
    grants = _re.findall(r"grant\s+select\s+on\s+([^;]+?)\s+to\s+(\w+)", low)
    assert grants and all(role == "service_role" for _, role in grants), grants
    assert "to anon" not in low and "to authenticated" not in low and "to public" not in low
    rev = low[low.index("revoke all on public.bot_config"):]
    assert "anon" in rev.split(";")[0] and "authenticated" in rev.split(";")[0]

    # exporter: every active bot resolves to a contract family
    from scripts import export_bot_config as ex
    contract = {"model_sim", "model_shadow", "sharp_trigger", "sharp_generator", "inplay",
                "forward_test", "control", "unknown"}
    assert set(ex.FAMILIES) == contract, ex.FAMILIES
    try:
        db_bots = ex._load_db_bots()
    except Exception:  # noqa: BLE001 — the source check must not need a DB
        db_bots = None
    rows = ex.build_rows(db_bots)
    by = {r["bot_name"]: r for r in rows}
    from workers.registry.bot_registry import active_names
    active = set(active_names())
    if db_bots:
        active |= {b["name"] for b in db_bots if b.get("retired_at") is None}
    assert len(by) == len(rows), "duplicate bot_config rows"
    for r in rows:
        assert r["family"] in contract, (r["bot_name"], r["family"])
        assert r["admissible_metric"] == ex.FAMILY_METRIC[r["family"]], r["bot_name"]
        for g in r["gates"]:
            assert set(g) == {"name", "value", "source"}, (r["bot_name"], g)
            # a source without a line number means src() missed — the code moved under us
            assert _re.search(r":\d+", g["source"]) or "env" in g["source"], (r["bot_name"], g)
    for n in active:
        assert n in by, f"active bot {n} missing from the export"
        assert by[n]["family"] != "unknown", f"active bot {n} has no resolvable config"
    assert by["control_junk_anchor"]["family"] == "control"
    # retired bots whose passes were deleted (#162 W7.2 (2026-09-26)) keep their family via _LINEAGE
    for n in ("bot_sweep_1x2_home_v1", "bot_sweep_1x2_draw_v1", "bot_sweep_ou25_v1", "bot_sweep_ou35_v1",
              "bot_pin_1x2_home_v1", "bot_no_pin_shadow_v1", "bot_no_pin_home_v1", "bot_coolbet_value_v1",
              "bot_trigger_1x2_model_v1", "bot_trigger_ou_model_v1"):
        if n in by:
            assert by[n]["family"] != "unknown", f"{n} lost its family — add it to export_bot_config._LINEAGE"
    assert not any(g["name"] == "anchor_sanity_ratio" for r in rows for g in r["gates"]), "placeholder gate"
    assert by["bot_inplay_slowstate_v1"]["admissible_metric"] == "lift"
    assert by["bot_v10_1x2"]["admissible_metric"] == "clv_anchor"   # [[#159]] one CLV everywhere
    sched = _engine_path("workers/scheduler.py").read_text()
    assert '_run_job("export_bot_config", _job_export_bot_config_impl)' in sched
    assert _re.search(r'job_export_bot_config, CronTrigger\(hour=3, minute=40\)', sched)


@test("ANON-LEAST-PRIVILEGE — the public API role reads only what the site reads (#072)")
def test_anon_least_privilege():
    """#072 (2026-09-24): anon held SELECT on 134/134 public relations via default privileges;
    RLS was the only control. Migration 404 revokes all, grants back exactly the relations
    createSupabasePublic() reads, drops anon from default privileges, and revokes EXECUTE on
    the SECURITY DEFINER odds functions (a definer function bypasses a table revoke).
    Adding a public surface = a *_public view + an explicit GRANT + this list."""
    import re as _re
    sql = _engine_path("supabase/migrations/404_anon_least_privilege.sql").read_text()
    assert "REVOKE SELECT ON ALL TABLES IN SCHEMA public FROM anon" in sql
    assert "ALTER DEFAULT PRIVILEGES FOR ROLE oddsintel_owner IN SCHEMA public REVOKE SELECT ON TABLES FROM anon" in sql
    grant = sql.split("GRANT SELECT ON", 1)[1].split("TO anon", 1)[0]
    granted = set(_re.findall(r"public\.(\w+)", grant))
    assert granted == {
        "simulated_bets", "bots", "matches", "teams", "leagues", "dashboard_cache",
        "match_page_views", "picks_forward_test_public", "picks_forward_test_summary",
        "picks_forward_test_summary_by_market", "picks_board_public", "picks_public_all",
    }, f"anon grant list changed: {sorted(granted)} — update this test deliberately"
    for base in ("picks_forward_test", "picks_board", "shadow_bets", "coolbet_placement_attempts"):
        assert base not in granted, f"{base} must stay private (serve it through a *_public view)"
    # 405: new FUNCTIONS are not executable by anon/PUBLIC by default either (a future
    # SECURITY DEFINER function would otherwise be public the moment it is created)
    f405 = _engine_path("supabase/migrations/405_anon_no_default_function_execute.sql").read_text()
    assert "REVOKE EXECUTE ON FUNCTIONS FROM anon" in f405 and "REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC" in f405
    for fn in ("get_best_match_odds", "get_latest_match_odds", "get_historical_match_odds",
               "get_bookmaker_count_for_match", "handle_new_user"):
        assert _re.search(rf"REVOKE EXECUTE ON FUNCTION public\.{fn}\(.*FROM anon, PUBLIC", sql), fn


@test("PICKS-FORWARD-TEST-AMENDED-CHECKPOINT — #156 stop rule = sharp-anchor CLV, live vs junk control")
def test_picks_forward_test_amended_checkpoint():
    """[[#156]] (2026-09-25, owner-approved, before live n=200). The pre-registered n=200/400
    stop rule was judged on own-book margin-corrected CLV, which cannot separate the live arm
    from the random junk-anchor control (−0.4pp [−1.9,+1.2]) because the rule picks legs a book
    misprices and that book's own close sits at ~−margin by construction. AMENDMENT 1: sharp-
    anchor CLV (clv_sharp, else >=5-book clv_cons, thin excluded), market-stratified live −
    control, one-sided bootstrap B=10k seed 20260925, CONTINUE only if p < 0.025 at n=200 and
    n=400. Guards: the pre-stated constants, the arithmetic, read-only, the thin exclusion, and
    that the amendment was APPENDED (the original rule text is still there, unedited)."""
    import inspect
    import scripts.picks_forward_test_checkpoint as ck
    assert ck.CHECKPOINTS == (200, 400) and ck.ALPHA == 0.025
    assert ck.BOOT_B == 10_000 and ck.SEED == 20260925 and ck.CLV_ABS_MAX == 1.0
    sql = ck.SQL
    # #162 W6.3 (migration 454): the pinnacle-else-consensus precedence is the SQL function
    # anchor_clv()/anchor_source() now, shared with the /performance views — ANCHOR-CLV-ONE-FUNCTION
    # pins its body. The checkpoint must call it rather than re-state it.
    assert "anchor_clv(c.status, c.cons_status, c.clv_sharp, c.clv_cons)" in sql
    assert "thin" not in sql, "3–4-book thin consensus must never enter the decision"
    assert "p.rule_version = %s" in sql and "'junk_anchor'" in sql and "('won', 'lost')" in sql
    src = inspect.getsource(ck)
    for w in ("INSERT ", "UPDATE ", "DELETE ", "execute_write"):
        assert w not in src.replace("UPDATED", ""), f"checkpoint script must be read-only ({w})"
    assert "SET TRANSACTION READ ONLY" in src
    # arithmetic: stratified by the LIVE arm's market shares
    c = {("live", "1x2"): [0.03, 0.01], ("junk_anchor", "1x2"): [-0.02, -0.02, -0.02],
         ("live", "ou"): [0.0], ("junk_anchor", "ou"): [-0.03]}
    d, per = ck.stratified_delta(c)
    assert abs(d - (2 / 3 * 0.04 + 1 / 3 * 0.03)) < 1e-12, d
    assert abs(per["1x2"]["w"] - 2 / 3) < 1e-12
    assert ck.stratified_delta({("live", "1x2"): [0.1]})[0] is None, "no control -> no statistic"
    assert ck.anchor_value({"clv_anchor": 1.5}) is None and ck.anchor_value({"clv_anchor": -0.2}) == -0.2
    p, lo = ck.bootstrap({k: v * 20 for k, v in c.items()}, b=300)
    assert p == 0.0 and lo > 0
    p2, _ = ck.bootstrap({("live", "m"): [0.01, -0.01] * 20, ("junk_anchor", "m"): [0.01, -0.01] * 20}, b=300)
    assert p2 > 0.2, "identical arms must not pass"
    assert ck.verdict(88, 0.0).startswith("NO CHECKPOINT YET")
    assert "CONTINUE" in ck.verdict(200, 0.01) and "STOP" in ck.verdict(200, 0.025)
    assert "n=400" in ck.verdict(450, 0.5) and "STOP" in ck.verdict(450, 0.5)
    assert "STOP" in ck.verdict(200, None)
    doc = _engine_path("dev/active/picks-forward-test-preregistration.md").read_text()
    assert "## AMENDMENT 1 — 2026-09-25" in doc
    assert "| **n = 200** | CLV (margin-corrected, `EV ≈ (1+clv)/(1+m) − 1`, m ≈ 7.6%) < −2% |" in doc, (
        "the original registered rule must stay in place, unedited — amendments are appended")
    assert doc.index("## AMENDMENT 1") > doc.index("## A second arm"), "the amendment is appended, not inserted"
    assert "scripts.picks_forward_test_checkpoint" in doc and "p < 0.025" in doc
    return f"ALPHA={ck.ALPHA} B={ck.BOOT_B}; amendment appended, original text intact"


@test("FORWARD-TEST-SHARP-ANCHOR-CLV-ON-PERFORMANCE — #156 main CLV = sharp close; current rule; unsent D out")
def test_forward_test_sharp_anchor_clv_on_performance():
    """[[#156]] (2026-09-25, owner-approved). /performance's forward-test rows (a) lead with the
    SHARP-ANCHOR CLV (clv_sharp, else >=5-book clv_cons) with its n and Pinnacle/consensus mix, the
    own-book figure only as a labelled secondary; (b) are scored on the CURRENT rule_version
    (as bot_scoreboard) — bot_sharp_1x2_v1 was pooling 8 picks of closed v1; (c) drop grade-D
    picks that were never sent (the filter picks_public_all has), written NULL-safe so a live
    pick recorded during a Telegram pause is NOT dropped. leg_clv_sharp stays private: the
    aggregate view is service_role only, so the ANON-LEAST-PRIVILEGE list does not change."""
    from workers.api_clients.db import execute_query
    mig = _engine_path("supabase/migrations/430_forward_test_sharp_anchor_clv.sql").read_text()
    null_safe = "NOT (grade IS NOT DISTINCT FROM 'D' AND telegram_message_id IS NULL)"
    assert mig.count(null_safe) == 2, "both summary views need the NULL-safe unsent-D filter"
    assert mig.count("NOT (p.grade IS NOT DISTINCT FROM 'D' AND p.telegram_message_id IS NULL)") == 2
    assert "grade = 'D'::text AND" not in mig, "the NULL-unsafe form drops paused live picks"
    for v in ("picks_forward_test_summary AS", "picks_forward_test_summary_by_market AS",
              "picks_forward_test_public AS", "public.picks_forward_test_anchor_clv AS"):
        assert f"CREATE OR REPLACE VIEW {v}" in mig, v
    assert "c.status = 'ok' THEN c.clv_sharp" in mig and "c.cons_status = 'ok' THEN c.clv_cons" in mig
    assert "thin" not in mig.split("CREATE OR REPLACE VIEW public.picks_forward_test_anchor_clv", 1)[1].split("COMMENT ON", 1)[0]
    assert "TO anon" not in mig and "TO authenticated" not in mig
    assert "REVOKE ALL ON public.picks_forward_test_anchor_clv FROM PUBLIC, anon, authenticated, service_role;" in mig
    assert "GRANT SELECT ON public.picks_forward_test_anchor_clv TO service_role;" in mig
    applied = {r["filename"] for r in execute_query("SELECT filename FROM _schema_migrations")}
    if "430_forward_test_sharp_anchor_clv.sql" in applied:
        r = execute_query("""SELECT has_table_privilege('anon', 'public.picks_forward_test_anchor_clv', 'SELECT') AS anon_can,
              (SELECT coalesce(sum(published), 0) FROM picks_forward_test_summary WHERE grade = 'D') AS d_view,
              (SELECT count(*) FROM picks_forward_test WHERE arm = 'consensus_anchor' AND grade = 'D'
                  AND telegram_message_id IS NOT NULL) AS d_sent""")[0]
        assert not r["anon_can"], "the anchor-CLV aggregate must not be readable by anon"
        assert int(r["d_view"]) == int(r["d_sent"]), f"unsent grade-D picks still in the summary: {r}"
    g = _engine_path("docs/ANALYSIS_GOTCHAS.md").read_text()
    assert "## 85. Own-book close CLV is negative BY CONSTRUCTION" in g
    web_lib = _web_path("src/lib/engine-data.ts").read_text()
    page = _web_path("src/app/(app)/performance/page.tsx").read_text()
    lb = _web_path("src/components/performance-leaderboard.tsx").read_text()
    # [[#158]] the reader moved to picks_forward_test_bot_record (same CLV definition, 431)
    i = web_lib.index("export async function getForwardTestBotRecord(")
    body = web_lib[i:i + 700]
    assert "createSupabaseAdmin()" in body and '.from("picks_forward_test_bot_record")' in body, (
        "the private aggregate must be read server-side with the service client")
    assert "getForwardTestBotRecord(x.arm, x.grade, x.market)" in page
    # [[#159]] the row's figures + sharp CLV come from bot_performance (same definition), the
    # own-book figure stays the labelled secondary from the #158 record.
    assert 'clvDirection: clv == null ? "neutral"' in page and "avgClv: isElite ? clv : null" in page
    assert "ownClv: cur.clvMarginCorrected" in page and "record?.current" in page and "?.pooled" not in page
    flat = " ".join(lb.split())
    assert "vs sharp close {clvPct(ft.sharpClv)}" in flat and "Pinnacle / ${ft.nConsensus} consensus" in flat
    assert "vs the book&apos;s own close" in flat, "own-book figure must stay, labelled as secondary"
    assert "measured{\" \"} <span className=\"text-foreground\">vs the sharp close</span>" in flat, "legend must explain CLV"
    return "sharp-anchor main CLV, current rule, unsent D filtered, private aggregate"


@test("RECHECK-FORWARD-TEST-PICK-TIME-ONLY — #158 earlier-rule picks re-checked on pick-time data count in the current record")
def test_recheck_forward_test_pick_time_only():
    """[[#158]] (2026-09-25, owner-approved). SENT consensus v1 picks are re-checked against v2
    (credible-method gate) by rebuilding the consensus from odds_snapshots AS OF published_at
    with the publisher's OWN functions; passing ones count in the bot's current /performance
    record (marked re-checked), failing ones stay in the "didn't meet today's rule" line. Pins:
    (1) the script never reads an outcome column; (2) it is idempotent (frozen verdicts);
    (3) its arithmetic is the publisher's (synthetic market, compared against load_candidates'
    own credible-min formula); (4) the view logic; (5) the web reads it."""
    import inspect
    from datetime import datetime, timedelta, timezone
    import scripts.recheck_forward_test_picks as rc
    import scripts.publish_picks_forward_test as pub
    from workers.model.devig import devig_by
    src = inspect.getsource(rc)
    sql = rc.PICKS_SQL + rc.QUOTES_SQL
    for col in ("outcome", "pnl", "closing", "clv", "settled_at", "leg_clv_sharp"):
        assert col not in sql.lower(), f"re-check SQL reads a result column: {col}"
    code = src.split('"""', 2)[2]                      # everything after the module docstring
    for col in ('["outcome"]', '["pnl"]', '["clv', '["closing', "settled_at"):
        assert col not in code, f"re-check code touches a result field: {col}"
    assert "o.timestamp <= %s" in rc.QUOTES_SQL and "interval '6 hours'" in rc.QUOTES_SQL
    assert "o.is_live IS NOT TRUE" in rc.QUOTES_SQL and "NOT (o.bookmaker = ANY(%s))" in rc.QUOTES_SQL
    assert "telegram_message_id IS NOT NULL" in rc.PICKS_SQL, "only SENT picks are re-checked"
    # (2) idempotent: frozen verdicts, never overwritten
    assert "ON CONFLICT (pick_id, checked_rule_version) DO NOTHING" in src and "DO UPDATE" not in src
    assert "if (p[\"id\"], target) in done:" in src
    # (3) the publisher's own functions and constants — not a copy
    for name in ("_consensus_anchor", "CREDIBLE_DEVIG_METHODS", "CONSENSUS_MIN_BOOKS",
                 "CONSENSUS_MAX_EDGE", "EXCLUDED_BOOKS", "MIN_EDGE"):
        assert name in src, name
    assert rc.CURRENT_RULE["consensus_anchor"] == pub.CONSENSUS_RULE_VERSION
    assert rc.CURRENT_RULE["live"] == pub.RULE_VERSION
    t = datetime(2026, 9, 23, 10, 0, tzinfo=timezone.utc)
    books = {"A": (2.00, 3.50, 3.80), "B": (2.05, 3.40, 3.70), "C": (1.95, 3.60, 3.90),
             "D": (2.02, 3.45, 3.75), "E": (1.98, 3.55, 3.85)}
    sides = pub.MARKETS["1x2"]
    side_q = {s: {b: (o[i], t - timedelta(minutes=5)) for b, o in books.items()} for i, s in enumerate(sides)}
    side_q["home"]["Soft"] = (2.20, t)
    probs, _, n_books = pub._consensus_anchor(sides, side_q)
    edge = probs["home"] * 2.20 - 1.0
    cm = edge
    for m in pub.CREDIBLE_DEVIG_METHODS:
        if m != "shin":
            ga = pub._consensus_anchor(sides, side_q, lambda o, m=m: devig_by(m, o))
            cm = min(cm, ga[0]["home"] * 2.20 - 1.0)
    ok, d = rc.evaluate_consensus_leg(side_q, sides, "home", 2.20, "Soft", stored_p=probs["home"])
    assert abs(d["edge_credible_min"] - cm) < 1e-6 and d["n_books"] == n_books
    assert ok == (cm >= pub.MIN_EDGE and pub.MIN_EDGE <= edge <= pub.CONSENSUS_MAX_EDGE)
    assert d["rebuild_reproduces_stored_p"] is True
    # a rebuild that does not reproduce the recorded probability cannot pass on a thin margin
    ok2, d2 = rc.evaluate_consensus_leg(side_q, sides, "home", 2.20, "Soft", stored_p=probs["home"] - 0.02)
    assert d2["rebuild_reproduces_stored_p"] is False and d2["mismatch_slack_on_edge"] > 0.04
    assert not ok2
    few = {s: {b: q for b, q in v.items() if b in ("A", "B", "Soft")} for s, v in side_q.items()}
    assert rc.evaluate_consensus_leg(few, sides, "home", 2.20, "Soft")[1]["reason"] == "no_pick_time_consensus"
    sharp = {"selection": "home", "odds": 2.0, "edge": 0.05, "anchor_odds": {"home": 1.9},
             "anchor_overround": 0.09, "alignment_gap_minutes": 5.0}
    assert rc.evaluate_sharp_leg(sharp)[1]["reason"] == "anchor_overround"
    # (4) view logic
    mig = _engine_path("supabase/migrations/431_pick_rule_recheck.sql").read_text()
    assert "PRIMARY KEY (pick_id, checked_rule_version)" in mig
    assert "rc.checked_rule_version = cur.current_rule_version" in mig, (
        "a verdict counts only against the arm's CURRENT rule")
    assert "WHEN rc.passes IS TRUE  THEN 'rechecked_pass'" in mig and "'rechecked_fail'" in mig
    assert mig.count("NOT (p.grade IS NOT DISTINCT FROM 'D' AND p.telegram_message_id IS NULL)") == 2
    assert "TO anon" not in mig and "TO authenticated" not in mig
    assert "REVOKE ALL ON public.pick_rule_recheck FROM PUBLIC, anon, authenticated, service_role;" in mig
    assert "coalesce(r.record_rule_version, p.rule_version) AS record_rule_version" in mig
    assert "r.record_state\n" in mig and "details" not in mig.split("CREATE OR REPLACE VIEW picks_forward_test_public", 1)[1]
    from workers.api_clients.db import execute_query
    applied = {r["filename"] for r in execute_query("SELECT filename FROM _schema_migrations")}
    live = ""
    if "431_pick_rule_recheck.sql" in applied:
        r = execute_query("""SELECT
              has_table_privilege('anon', 'public.pick_rule_recheck', 'SELECT') AS anon_t,
              has_table_privilege('anon', 'public.picks_forward_test_bot_record', 'SELECT') AS anon_v,
              (SELECT count(*) FROM picks_forward_test_record_leg l JOIN pick_rule_recheck c ON c.pick_id = l.id
                WHERE c.passes AND c.checked_rule_version = l.current_rule_version
                  AND l.record_rule_version <> l.current_rule_version) AS pass_not_current,
              (SELECT count(*) FROM picks_forward_test_record_leg l JOIN pick_rule_recheck c ON c.pick_id = l.id
                WHERE NOT c.passes AND l.record_state <> 'rechecked_fail') AS fail_counted,
              (SELECT coalesce(sum(published), 0) FROM picks_forward_test_bot_record) AS rec_n,
              (SELECT count(*) FROM picks_forward_test_public) AS pub_n,
              -- [[#164]] VIP FIRST: a held-back pick is in the record but not on the public list
              -- until kickoff (migration 439), so the two differ by exactly the held-back picks.
              (SELECT count(*) FROM picks_forward_test p WHERE p.arm IN ('live', 'consensus_anchor')
                  AND p.held_back_until > now()
                  AND NOT (p.grade IS NOT DISTINCT FROM 'D' AND p.telegram_message_id IS NULL)) AS held_n,
              (SELECT count(*) FROM pick_rule_recheck) AS n_checks""")[0]
        assert not r["anon_t"] and not r["anon_v"], "re-check table / record view must stay private"
        assert r["pass_not_current"] == 0 and r["fail_counted"] == 0, r
        assert int(r["rec_n"]) == int(r["pub_n"]) + int(r["held_n"]), f"bot record and the public list disagree: {r}"
        live = f"; {r['n_checks']} verdicts live"
    # (5) web
    web_lib = _web_path("src/lib/engine-data.ts").read_text()
    page = _web_path("src/app/(app)/performance/page.tsx").read_text()
    lb = _web_path("src/components/performance-leaderboard.tsx").read_text()
    i = web_lib.index("export async function getForwardTestBotRecord(")
    body = web_lib[i:i + 700]
    assert "createSupabaseAdmin()" in body and '.from("picks_forward_test_bot_record")' in body
    # [[#159]] the bet list = the row's record legs (bot_ledger in_record, built on
    # picks_forward_test_record_leg); the row reads nRechecked from the #158 record
    mig433 = _engine_path("supabase/migrations/433_one_bot_performance.sql").read_text()
    assert "LEFT JOIN picks_forward_test_record_leg r ON r.id = p.id" in mig433
    assert "COALESCE(r.record_state IN ('native', 'rechecked_pass'), false) END AS in_record" in mig433
    assert "getForwardTestBotRecord(x.arm, x.grade, x.market)" in page and "nRechecked: cur.nRechecked" in page
    flat = " ".join(lb.split())
    assert "re-checked under {ft.rule}" in flat and "didn't meet today's rule" in flat
    return "pick-time only, frozen verdicts, publisher arithmetic, private views" + live


