@test("RATING-1X2-BOT — #141 '1x2 market NEW' is an exact twin of bot_v10_1x2 except its 1X2 probability")
def test_rating_1x2_bot_twin():
    """RATING-1X2-BOT ([[#141]], 2026-09-24). The bot exists to answer ONE question —
    does the rating model pick better 1X2 bets than bot_v10_1x2 — so every rule other
    than the probability source must stay identical, and the rating probability must
    NOT pass through calibrate_prob (with 1X2 shrinkage alpha ~0 that step returns
    Platt(Pinnacle) and the twin would copy the market bot)."""
    from workers.jobs.daily_pipeline_v2 import BOTS_CONFIG, BOT_TIMING_COHORTS
    new, old = BOTS_CONFIG["bot_rating_1x2_v1"], BOTS_CONFIG["bot_v10_1x2"]
    assert new["prob_source"] == "rating_1x2" and "prob_source" not in old
    for k in ("markets", "tier_filter", "edge_thresholds", "odds_range", "min_prob"):
        assert new[k] == old[k], f"twin drifted on {k}: {new[k]} vs {old[k]}"
    assert BOT_TIMING_COHORTS["bot_rating_1x2_v1"] == BOT_TIMING_COHORTS["bot_v10_1x2"]
    comb = BOTS_CONFIG["bot_combined_1x2_v1"]          # second arm, combined model (round 3b)
    assert comb["prob_source"] == "combined_1x2"
    for k in ("markets", "tier_filter", "edge_thresholds", "odds_range", "min_prob"):
        assert comb[k] == old[k], f"combined twin drifted on {k}"
    assert BOT_TIMING_COHORTS["bot_combined_1x2_v1"] == BOT_TIMING_COHORTS["bot_v10_1x2"]
    src = _engine_path("workers/jobs/daily_pipeline_v2.py").read_text(encoding="utf-8")
    i = src.index('if _rating_bot or (_ou_new and mkt == "O/U"):\n                    cal_prob = raw_mp')  # #152 added O/U
    assert "calibrate_prob(" in src[i:i + 600], "the non-rating path must still calibrate"
    assert '_funnel[bot_name]["drop_no_rating"]' in src, "no rating row must mean no bet, never a fallback price"
    assert 'candidate_specs.append(("1X2", "Home", odds, _p1x2["home_prob"]' in src
    mig = _engine_path("supabase/migrations/414_bot_rating_1x2.sql").read_text(encoding="utf-8")
    assert "'experimental'" in mig and "'1x2 market NEW'" in mig
    assert "INSERT INTO coolbet_placer_bots" not in mig, "no real-money eligibility row for this bot"


@test("MARKET-CONSENSUS-1X2 — #141 de-vigged multi-book consensus: Pinnacle separate, excluded books ignored, outliers dropped")
def test_market_consensus_1x2():
    """MARKET-CONSENSUS-1X2 ([[#141]] round 3b). The combined 1X2 model's market input.
    Its value rests on four rules: Pinnacle is a separate input and never inside the
    consensus; excluded books (SBO, Unibet-Kambi, Avg/Max, the exchange) never count;
    a book > 0.25 from the others' median (a transposed or wrong-fixture price) is
    dropped; the three legs of a triple must be written within 120 s of each other."""
    import pandas as pd
    from workers.model.market_consensus_1x2 import consensus, CONSENSUS_BOOKS
    assert "Pinnacle" not in CONSENSUS_BOOKS and "SBO" not in CONSENSUS_BOOKS
    assert "Unibet-Kambi" not in CONSENSUS_BOOKS and "Avg" not in CONSENSUS_BOOKS
    rows = []
    def add(book, h, d, a, t=0.0, mid="m1"):
        for sel, o in (("home", h), ("draw", d), ("away", a)):
            rows.append(dict(match_id=mid, bookmaker=book, selection=sel, odds=o, ts=t))
    add("Pinnacle", 2.00, 3.50, 4.00)
    add("Bet365", 2.00, 3.40, 3.90); add("1xBet", 2.05, 3.40, 3.80); add("Betano", 1.95, 3.50, 4.00)
    add("Coolbet", 6.00, 4.00, 1.50)                      # transposed home/away -> outlier
    # NB the 0.25 guard only catches LARGE inversions: a 2.00/4.00 swap moves home prob
    # ~0.22 and passes; the write-time mirror guard (#006) is the defence for those.
    add("SBO", 1.20, 6.00, 12.0)                           # excluded book, must not move the consensus
    add("Epicbet", 2.00, 3.40, 3.90, t=0.0); rows[-1]["ts"] = 500.0   # legs 500 s apart -> rejected
    c = consensus(pd.DataFrame(rows)).loc["m1"]
    assert c.n_books == 3, f"expected Bet365/1xBet/Betano only, got n_books={c.n_books}"
    assert 0.45 < c.c_h < 0.52 and abs(c.c_h + c.c_d + c.c_a - 1) < 1e-9
    assert abs(c.pin_h - (1/2.0) / (1/2.0 + 1/3.5 + 1/4.0)) < 1e-9, "Pinnacle must be its own de-vigged input"


@test("COMBINED-1X2 — #141 per-group combiner: AF only where unpriced, rule fallback, probabilities valid, refresh wired")
def test_combined_1x2():
    """COMBINED-1X2 ([[#141]] round 3b, COMB-HYB). Adopted on a pre-registered test
    (0.9763 vs 1.0711 log-loss for the shipped head). Pins the three design rules
    the result depends on: one model per availability group (a missing source is not
    a zero), API-Football only in the no-price group (it hurt where the market
    exists), and a group without fitted params falls back to Pinnacle > consensus >
    rating rather than to nothing. Also pins the 30-min refresh job."""
    import numpy as np
    import pandas as pd
    from workers.model.combined_1x2 import fit, predict, design
    rng = np.random.default_rng(1)
    n = 2400
    def tri(k):
        x = rng.dirichlet([4, 2.5, 3], k); return x
    d = pd.DataFrame(tri(n), columns=["r_h", "r_d", "r_a"])
    c = tri(n); d[["c_h", "c_d", "c_a"]] = c; d["n_books"] = rng.integers(1, 9, n)
    d[["pin_h", "pin_d", "pin_a"]] = tri(n)
    d[["af_h", "af_d", "af_a"]] = [0.45, 0.45, 0.10]; d["af_th"] = 0.5
    d.loc[800:1599, ["pin_h", "pin_d", "pin_a"]] = np.nan                      # C only
    d.loc[1600:, ["pin_h", "pin_d", "pin_a", "c_h", "c_d", "c_a"]] = np.nan    # none
    d["y"] = [rng.choice(3, p=p) for p in c]
    params = fit(d)
    assert set(params) == {"P&C", "C", "none"}, params.keys()
    assert np.asarray(params["P&C"]["coef"]).shape[1] == 7, "P&C = rating(2)+consensus(2)+log n(1)+Pinnacle(2), NO AF"
    assert np.asarray(params["none"]["coef"]).shape[1] == 6, "none = rating(2)+AF percent(2)+AF total(1)+has_af(1)"
    assert design(d.iloc[:5], "C").shape[1] == 5, "C = rating + consensus + log n_books, no AF"
    P, grp = predict(d, params)
    assert np.allclose(P.sum(1), 1) and (P > 0).all()
    only_p = d.iloc[:3].copy(); only_p[["c_h", "c_d", "c_a"]] = np.nan
    Pp, gp = predict(only_p, params)                                          # 'P' has no params -> Pinnacle
    assert (gp == "P").all() and np.allclose(Pp, only_p[["pin_h", "pin_d", "pin_a"]].to_numpy())
    sched = _engine_path("workers/scheduler.py").read_text(encoding="utf-8")
    assert 'id="combined_1x2_refresh"' in sched
    body = sched[sched.index("def job_combined_1x2_refresh"):sched.index("def job_weekly_meta_retrain")]
    assert '"workers.jobs.rating_1x2_shadow", "--refresh"' in body, "refresh must run in a subprocess"
    job = _engine_path("workers/jobs/rating_1x2_shadow.py").read_text(encoding="utf-8")
    assert "INTO predictions" not in job and "to_datetime" not in job


@test("PLAYER-STRENGTH-LEAK-GUARD — #141 round 3c XI features never read the same day's player ratings")
def test_player_strength_leak_guard():
    """PLAYER-STRENGTH ([[#141]] round 3c). A player's rating from match X must not feed
    match X's own XI feature (API-Football ratings are post-match and track the result),
    nor any fixture the same day. Behavioural, on synthetic data."""
    import pandas as pd
    from workers.model.player_strength_1x2 import build_xi_features, PRIOR
    fx = pd.DataFrame({"fixture_id": [1, 2, 3], "kickoff": [0.0, 3600.0, 86400.0 * 5],
                       "home_af": [10, 30, 10], "away_af": [20, 40, 20]})
    xi10, xi20 = ",".join(str(i) for i in range(100, 111)), ",".join(str(i) for i in range(200, 211))
    lu = pd.DataFrame({"fixture_id": [1, 1, 3, 3], "team_id": [10, 20, 10, 20], "xi": [xi10, xi20, xi10, xi20]})
    pl = pd.DataFrame({"fixture_id": [1] * 22, "player_id": list(range(100, 111)) + list(range(200, 211)),
                       "minutes": [90] * 22, "rating": [9.0] * 11 + [5.0] * 11})
    out = build_xi_features(fx, pl, lu).set_index("fixture_id")
    assert abs(out.loc[1, "xi_h"] - PRIOR) < 1e-9 and abs(out.loc[1, "xi_diff"]) < 1e-9, \
        "fixture 1 read its own post-match ratings"
    assert out.loc[3, "xi_diff"] > 0.5, "ratings from fixture 1 must reach fixture 3 five days later"
    assert out.loc[3, "prev_diff"] > 0.5, "PREV (last known XI) must be available by fixture 3"


@test("BACKTEST-1X2-NEW-BOTS — #141 B: fixed window, read-only, never writes simulated_bets, gates pinned to the pipeline")
def test_backtest_1x2_new_bots():
    """BACKTEST-1X2-NEW-BOTS ([[#141]] step B). The honest backtest of bot_v10_1x2 /
    bot_rating_1x2_v1 / bot_combined_1x2_v1 is only honest if (a) the window stays the
    owner's pre-registered 2026-08-31..2026-09-24 — no window picked by result, (b) it
    never writes to simulated_bets or any table (results live in a gitignored research
    dir, labelled "Backtest (simulated)"), and (c) the funnel constants it had to copy
    (they are locals in run_morning / _load_today_from_db) still match the pipeline.
    Source inspection only: importing the script would open a DB connection."""
    import ast
    from datetime import datetime, timezone
    src = _engine_path("scripts/backtest_1x2_new_bots.py").read_text(encoding="utf-8")
    consts = {}
    for node in ast.parse(src).body:
        if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
            try:
                consts[node.targets[0].id] = ast.literal_eval(node.value)
            except ValueError:
                pass
    assert consts["WINDOW_START"] == "2026-08-31" and consts["WINDOW_END"] == "2026-09-24", "window is pre-registered"
    ep = lambda d: datetime.fromisoformat(d).replace(tzinfo=timezone.utc).timestamp()
    assert consts["WINDOW_START_EPOCH"] == ep("2026-08-31") and consts["WINDOW_END_EPOCH"] == ep("2026-09-25")
    assert "NEW_TRAIN_CUT_EPOCH = WINDOW_START_EPOCH" in src, "NEW must be fitted before the window only"
    low = src.lower()
    for bad in ("insert into", "update ", "delete from", "store_bet(", "execute_values", "bulk_store", "create table"):
        assert bad not in low, f"backtest must be read-only; found {bad!r}"
    assert "readonly=True" in src, "DB connection must be opened read-only"
    assert '"_research" / "1x2" / "backtest"' in src, "output must stay in the gitignored research dir"
    assert "Backtest (simulated)" in src
    pipe = _engine_path("workers/jobs/daily_pipeline_v2.py").read_text(encoding="utf-8")
    assert f"PINNACLE_VETO_GAP = {consts['PINNACLE_VETO_GAP']}" in pipe
    assert 'DATA_TIER_EDGE_BUMP = {"A": 0.00, "B": 0.02, "C": 0.08}' in pipe and \
        consts["DATA_TIER_EDGE_BUMP"] == {"A": 0.0, "B": 0.02, "C": 0.08}
    assert '_ALN_BUMP = {"LOW": 0.01, "MEDIUM": 0.0, "HIGH": 0.0, "NONE": 0.0}' in pipe
    assert f'"1x2": {consts["OUTLIER_MULT_1X2"]},' in pipe and f"_OUTLIER_MIN_BOOKS = {consts['OUTLIER_MIN_BOOKS']}" in pipe
    assert "if tier >= 3 and thresholds:" in pipe and '(0.05 if k.startswith("1x2") else 0.03)' in pipe
    assert "0.06 <= _anchor_gap < 0.10" in pipe and "edge < me + 0.02" in pipe
    sc = _engine_path("workers/api_clients/supabase_client.py").read_text(encoding="utf-8")
    assert '_SOFT_BMS = {"Bwin", "Unibet", "Sportingbet", "Betway", "NordicBet", "10Bet", "1xBet"}' in sc
    assert consts["SOFT_BMS"] == {"Bwin", "Unibet", "Sportingbet", "Betway", "NordicBet", "10Bet", "1xBet"}
    assert "not_replicated" in src and "meta gate" in src, "gates not replicated must be listed in the output"


@test("BACKTEST-1X2-NEWPLUS-B2 — #141 B2: the four pre-registered NEW+ arms, Holm m=4, fixed window")
def test_backtest_1x2_newplus_b2():
    """BACKTEST B2 ([[#141]]). Pre-registered in dev/active/1x2-model-rebuild-plan.md
    ("Pre-registration — BACKTEST B2") BEFORE the run: NEW+ only, edge = p*odds - 1,
    Pinnacle required, one pick per match, arms N1-N4 fixed. Pins the arms so they
    cannot be re-tuned on the output. Source inspection only."""
    import ast
    src = _engine_path("scripts/backtest_1x2_new_bots.py").read_text(encoding="utf-8")
    consts = {}
    for node in ast.parse(src).body:
        if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
            try:
                consts[node.targets[0].id] = ast.literal_eval(node.value)
            except ValueError:
                pass
    assert consts["B2_ARMS"] == {
        "N1": {"ev_min": 0.03, "odds_range": (1.30, 6.00)},
        "N2": {"ev_min": 0.05, "odds_range": (1.30, 6.00)},
        "N3": {"ev_min": 0.08, "odds_range": (1.30, 6.00)},
        "N4": {"ev_min": 0.05, "odds_range": (2.00, 6.00)},
    }, "B2 arms are pre-registered — do not change them"
    assert consts["B2_HOLM_M"] == 4 and consts["B2_ALPHA"] == 0.05 and consts["B2_N_BOOT"] >= 10000
    assert consts["WINDOW_START"] == "2026-08-31" and consts["WINDOW_END"] == "2026-09-24"
    assert consts["B2_NULL_RANGE"] == (1.30, 6.00)
    assert 'frozenset({"Coolbet", "Unibet-Site", "Epicbet", "Tonybet"})' in src
    body = src[src.index("def run_b2_arm"):src.index("def _p_one_sided")]
    assert "ev = p * odds - 1" in body, "B2 edge is expected value"
    assert 'drop_no_pinnacle' in body and "min_prob" not in body and "startswith(\"1x2\")" not in body, \
        "B2: Pinnacle required, no min_prob, no tier bump"
    assert "max(accepted)" in body, "one pick per match: the best-EV selection"
    assert "_b2.csv" in src and "_b2.json" in src and '"--b2" in _args' in src


@test("BACKTEST-1X2-GRID-B3 — #141 B3: pre-registered grid dimensions, split date, Holm m=10, SPA resamples, #065 un-swap")
def test_backtest_1x2_grid_b3():
    """BACKTEST B3 ([[#141]]). Exploratory grid pre-registered in
    dev/active/1x2-model-rebuild-plan.md ("Pre-registration — BACKTEST B3") BEFORE the
    run. Its honesty is the design — select on 08-31..09-12, confirm the top 10 ONCE on
    09-13..09-24 with Holm m=10, and Hansen SPA over kickoff dates — so the design
    constants are pinned here. Also pins the #065 un-swap of the baseline's stored XGB
    leg (served home/away swapped until 50ec7347). Source inspection only."""
    import ast
    from datetime import datetime, timezone
    src = _engine_path("scripts/backtest_1x2_new_bots.py").read_text(encoding="utf-8")
    c = {}
    for node in ast.parse(src).body:
        if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
            try:
                c[node.targets[0].id] = ast.literal_eval(node.value)
            except ValueError:
                pass
    assert c["B3_MODELS"] == ("baseline", "new", "newplus")
    assert c["B3_THRESH"] == {"pp": (0.02, 0.04, 0.06, 0.08, 0.10, 0.12), "ev": (0.02, 0.04, 0.06, 0.08, 0.12, 0.16)}
    assert c["B3_ODDS_MIN"] == (1.30, 1.60, 2.00, 2.50) and c["B3_ODDS_MAX"] == (3.00, 4.50, 6.00, 10.00)
    assert c["B3_SELECTIONS"] == ("all", "home", "draw", "away") and c["B3_PIN_REQUIRED"] == (True, False)
    assert c["B3_BOOKSETS"] == ("all", "af", "direct")
    n_ranges = sum(1 for a in c["B3_ODDS_MIN"] for b in c["B3_ODDS_MAX"] if a < b)
    assert 3 * 2 * 6 * n_ranges * 4 * 2 * 3 == 13824, "grid size drifted from the pre-registration (~12k)"
    ep = lambda d: datetime.fromisoformat(d).replace(tzinfo=timezone.utc).timestamp()
    assert c["B3_SPLIT_EPOCH"] == ep("2026-09-13"), "select 08-31..09-12, confirm 09-13..09-24"
    assert c["B3_MIN_CLV_N"] == 30 and c["B3_TOP_K"] == 10 and c["B3_HOLM_M"] == 10 and c["B3_ALPHA"] == 0.05
    assert c["B3_SPA_N_BOOT"] >= 2000 and c["B3_N_BOOT"] >= 10000 and isinstance(c["B3_SEED"], int)
    assert c["WINDOW_START"] == "2026-08-31" and c["WINDOW_END"] == "2026-09-24"
    assert c["UNSWAP_065"] is True and c["SWAP_FIX_EPOCH"] == ep("2026-09-14T07:08:48"), "#065 fix = commit 50ec7347"
    assert "Xu = X[[2, 1, 0]]" in src, "un-swap must put the XGB leg's home/away back"
    assert "_b3.csv" in src and "_b3.json" in src and '"--b3" in _args' in src


