@test("NEWPLUS-EV-BOTS — #141 B4: EV5/EV8 bots gate on EV, need Pinnacle, one pick per match, store pp edge")
def test_newplus_ev_bots():
    """B4 ([[#141]], pre-registered in dev/active/1x2-model-rebuild-plan.md). The two NEW+
    EV bots are only the pre-registered rules if: EV = p x odds - 1 is the gate (flat,
    no T3+ bump), a Pinnacle price is required, min_prob is off, odds 1.30-6.00, one
    pick per match — and the STORED edge stays probability points, because store_bet
    derives cal - 1/odds and VETO_EDGE_CAP is in that unit."""
    from workers.jobs.daily_pipeline_v2 import BOTS_CONFIG, BOT_TIMING_COHORTS
    from workers.registry.bot_registry import BOTS
    names = {b.name for b in BOTS}
    # bot_combined_1x2_ev8_v1 retired 2026-09-25 (migration 444) — a strict subset of EV5.
    for name, thr in (("bot_combined_1x2_ev5_v1", 0.05),):
        c = BOTS_CONFIG[name]
        assert c["prob_source"] == "combined_1x2" and c["edge_unit"] == "ev"
        assert c["require_pinnacle"] is True and c["one_per_match"] is True
        assert c["odds_range"] == (1.30, 6.00) and c["min_prob"] == 0.0 and c["markets"] == ["1x2"]
        assert all(v == {"1x2_fav": thr, "1x2_long": thr} for v in c["edge_thresholds"].values())
        assert set(c["edge_thresholds"]) == {1, 2, 3, 4}
        assert BOT_TIMING_COHORTS[name] == BOT_TIMING_COHORTS["bot_combined_1x2_v1"]
        assert name in names, f"{name} missing from bot_registry"
    src = _engine_path("workers/jobs/daily_pipeline_v2.py").read_text(encoding="utf-8")
    assert 'edge = cal_prob * odds - 1 if config.get("edge_unit") == "ev" else cal_prob - ip' in src
    assert 'if config.get("edge_unit") == "ev":\n                pass' in src and "elif tier >= 3 and thresholds:" in src
    assert 'if config.get("require_pinnacle") and pin_anchor is None:' in src
    assert src.count('"edge": cal_prob - ip,') >= 3, "store_bet, shadow rows AND the Telegram buffer carry the pp edge"
    assert "if _one_done:" in src and "_one_done = False" in src
    mig = _engine_path("supabase/migrations/418_bot_combined_1x2_ev.sql").read_text(encoding="utf-8")
    assert "'experimental', false" in mig and mig.count("'experimental', false") == 2, "paper + hidden from /picks"


@test("PREDICTIONS-SHADOW-OWN-SOURCE — #147: candidate-model rows never share source with production")
def test_predictions_shadow_own_source():
    """#147 PREDICTIONS-1X2-VERSION-MIXING. The shadow (candidate) model's rows were written
    with source='ensemble'/'xgboost' and told apart only by model_version, which ~15 readers
    never filter — calibration fits, the ML ETL, shadow passes, in-play, triggers, previews
    all mixed the candidate in. Now: *_shadow sources, existing rows migrated, the two A/B
    readers read both, fit_platt keyed on the 1X2 head's version, drift alert query valid."""
    pipe = _engine_path("workers/jobs/daily_pipeline_v2.py").read_text(encoding="utf-8")
    assert '"source": "ensemble_shadow",' in pipe and '"source": "xgboost_shadow",' in pipe
    import re as _re
    for m in _re.finditer(r'"reasoning": f"data_tier=\{data_tier\} shadow=', pipe):
        block = pipe[max(0, m.start() - 700):m.start()]
        assert '_shadow",' in block.split('"source":')[-1], "every shadow= row must carry a *_shadow source"
    mig = _engine_path("supabase/migrations/419_predictions_shadow_source.sql").read_text(encoding="utf-8")
    assert "SET source = 'ensemble_shadow'" in mig and "SET source = 'xgboost_shadow'" in mig
    assert mig.count("reasoning LIKE '%shadow=%'") == 2
    cm = _engine_path("scripts/compare_models.py").read_text(encoding="utf-8")
    assert "source IN ('ensemble', 'ensemble_shadow')" in cm, "A/B must still see the candidate"
    sb = _engine_path("scripts/model_version_clv_scoreboard.py").read_text(encoding="utf-8")
    assert "p.source IN ('ensemble', 'ensemble_shadow')" in sb
    sch = _engine_path("workers/scheduler.py").read_text(encoding="utf-8")
    assert 'fit_and_store(model_version=os.getenv("MODEL_VERSION"))' not in sch
    assert '_resolve_version("1x2")' in sch
    ha = _engine_path("workers/jobs/health_alerts.py").read_text(encoding="utf-8")
    assert "AVG(probability)" not in ha and "AVG(model_probability)" in ha


@test("B5-OUTLIER-PERSISTENCE — #141 B5: pre-registered takeability rule constants, read-only, cadence flag")
def test_b5_outlier_persistence():
    """B5 ([[#141]]). Pre-registered in dev/active/1x2-model-rebuild-plan.md ("Pre-registration
    — B5: are outlier quotes takeable?") BEFORE looking at the data: a book is NAMEABLE in
    paid picks iff >= 60% of its EV>=5% episodes are still EV>=5% at +15 min AND median
    persistence >= 30 min AND single-snapshot episodes <= 25%; < 30 episodes = INSUFFICIENT.
    Pins the rule so it cannot be re-tuned after the result. Source inspection only."""
