    assert 'key: "fixed"' in ch and 'key: "still"' in ch and 'key: "failed"' not in ch
    fx = _engine_path("scripts/admin_fixtures/jobs.py").read_text(encoding="utf-8")
    assert "FROM retired_jobs" in fx


