@test("SHARP-ANCHOR-MAX-AGE — pick_generator's sharp fair price never comes from a stale Pinnacle line")
def test_sharp_anchor_max_age():
    """#162 W8.3 (2026-09-25). `_candidates_from_sharp` de-vigs the latest Pinnacle line per selection with
    NO age limit, on a path that can feed real money (the per-book sharp trigger bots are capable). A line
    is now dropped when any side is older than SHARP_ANCHOR_MAX_AGE_H, or older than
    SHARP_ANCHOR_NEAR_KO_MAX_AGE_H within SHARP_ANCHOR_NEAR_KO_H of kick-off (where a pulled or moved
    market makes the "fair" price fiction). Exercised with the DB read faked on this thread only."""
    # #162 W7.6 (2026-09-26): `_candidates_from_sharp` is gone — every sharp bot's fair price comes from
    # sharp_engine.anchor_fair, which applies this rule; exercised there (was: the generator's SQL faked).
    from workers.automation import sharp_engine as se
    from workers.automation.bot_configs import ALL_CONFIGS
    from workers.automation.pick_generator import sharp_rule_for
    cfg = next(c for c in ALL_CONFIGS if c.prob_source == "sharp_devig" and c.markets[0] == "1x2")
    now = 1_000_000.0
    def pin(age_h):
        return {s: (o, now - age_h * 3600) for s, o in (("home", 2.10), ("draw", 3.40), ("away", 3.80))}
    ok = {mid: se.anchor_fair(sharp_rule_for(cfg), pin(age), ("home", "draw", "away"), now, now + ko * 3600)
          for mid, age, ko in (("fresh", 0.5, 30), ("old_far", 8.0, 60), ("old_near", 3.0, 5), ("ok_far", 6.5, 60))}
    mids = {m for m, p in ok.items() if p is not None}
    assert mids == {"fresh", "ok_far"}, mids
    from workers.utils import anchor as an
    # 7 h: tomorrow's fixtures are refreshed at 10:00 and 16:00 UTC — a 6 h cap would drop them just before 16:00
    assert an.SHARP_ANCHOR_MAX_AGE_H == 7.0 and an.SHARP_ANCHOR_NEAR_KO_MAX_AGE_H == 2.0 and an.SHARP_ANCHOR_NEAR_KO_H == 12.0
    # ONE rule: the sharp engine calls the shared helper, and every sharp producer goes through the engine
    src = _engine_path("workers/automation/sharp_engine.py").read_text(encoding="utf-8")
    assert "anchor_line_too_old(" in src and "from workers.utils.anchor import anchor_line_too_old" in src, \
        "the sharp engine must call the shared W8.3 rule, imported"


@test("FAIR-PRICE-ONE-RULE — one written de-vig rule per market shape, and every live copy pinned to its method")
def test_fair_price_one_rule():
    """#162 W3.1/W3.2 (2026-09-25). The audit found fair probability computed four ways, so CLV judged a pick
    with a different fair price from the one that chose it. `devig.fair_prob` + FAIR_METHOD_BY_SHAPE is the
    written rule (Shin for 3-way per ANALYSIS_GOTCHAS #78, power for 2-way). Each separate copy still in
    production is pinned here to the reference method it implements, so a silent edit to one copy fails CI;
    the proportional users are listed so none is added. Moving a live caller is #162 W3.3 (twin + OK)."""
    import math
    from workers.model import devig as dv
    assert dv.FAIR_METHOD_BY_SHAPE == {3: "shin", 2: "power"}
    three = [(2.10, 3.40, 3.80), (1.35, 5.20, 9.50), (4.20, 3.60, 1.90)]
    two = [(1.90, 1.95), (1.55, 2.55), (3.10, 1.38)]
    for o in three:
        assert dv.fair_prob(list(o)) == dv.shin_devig(list(o))
    for o in two:
        assert dv.fair_prob(list(o)) == dv.power_devig(list(o))
    assert dv.fair_prob([1.9, None]) is None and dv.fair_prob([1.0, 2.0]) is None

    close = lambda a, b: math.isclose(a, b, abs_tol=1e-6)
    # power copies (live): VIP #2's job and the combined O/U model
    from workers.jobs.ou_sharp_outlier import power_devig as vip2_power
    from workers.model.combined_ou import power_devig as ou_power
    for o in two:
        ref = dv.power_devig(list(o))[0]
        assert close(vip2_power(*o), ref), ("ou_sharp_outlier.power_devig drifted", o)
        assert close(float(ou_power(o[0], o[1])), ref), ("combined_ou.power_devig drifted", o)
    # proportional copies (known violations of #78 — to move under W3.3, never to spread)
    from workers.jobs.corners_paper_bot import _devig_two_way as corners_prop
    from workers.jobs.team_total_paper_bot import _devig_two_way as tt_prop
    for o in two:
        ref = dv.proportional_devig(list(o))
        assert close(corners_prop(*o)[0], ref[0]) and close(tt_prop(*o)[0], ref[0])
    # no NEW module may define its own de-vig: the set of files that do is frozen
    import re
    allowed = {"workers/model/devig.py", "workers/model/combined_ou.py", "workers/jobs/ou_sharp_outlier.py",
               "workers/jobs/corners_paper_bot.py", "workers/jobs/team_total_paper_bot.py"}
    found = set()
    for f in _engine_root.joinpath("workers").rglob("*.py"):
        txt = f.read_text(encoding="utf-8", errors="ignore")
        if re.search(r"^def _?(power|shin|proportional|additive)_?devig|^def _devig_two_way", txt, re.M):
            found.add(str(f.relative_to(_engine_root)))
    assert found <= allowed, f"new de-vig copy outside workers/model/devig.py: {sorted(found - allowed)} — use devig.fair_prob"


@test("CLV-SHARP-REAL-BETS — real money is judged on the same sharp-anchor close as every bot, confirmed singles only")
def test_clv_sharp_real_bets():
    """#162 W6.4 (2026-09-25). real_bets had only the legacy own-book close (no age limit), so the money
    page and the bot pages judged CLV differently. clv_sharp scores a fourth ledger 'real_bets' at the odds
    actually taken ('executed'), CONFIRMED placements only (placed_real IS TRUE — the NULL rows still mix
    legacy real bets with unlabelled paper rows until #162 W4.1) and singles only. Every view that reads
    leg_clv_sharp joins on an explicit ledger, so real-bet rows never reach a bot's score."""
    from workers.jobs import clv_sharp as cs
    sql = cs._LEGS_SQL["real_bets"]
    assert "r.placed_real IS TRUE" in sql and "r.combo_legs IS NULL" in sql and "'executed' basis" in sql
    from workers.api_clients.db import execute_query
    try:
        rows = execute_query("""SELECT count(*) AS n FROM leg_clv_sharp c LEFT JOIN real_bets r ON r.id = c.leg_id
                                 WHERE c.ledger = 'real_bets' AND (r.id IS NULL OR r.placed_real IS NOT TRUE)""")
        views = execute_query("""SELECT viewname, pg_get_viewdef(viewname::regclass) AS d FROM pg_views
                                  WHERE schemaname = 'public' AND definition ILIKE '%%leg_clv_sharp%%'""")
    except Exception:  # noqa: BLE001 — no DB in this environment
        return
    assert rows[0]["n"] == 0, "a real_bets CLV row must belong to a confirmed placement"
    for v in views:
        joins = v["d"].count("leg_clv_sharp c")
        assert v["d"].count("c.ledger = '") >= joins or "ledger" in v["d"], v["viewname"]


@test("BOT-DISTRIBUTION-AND-REVIEW-FLAG — who-gets-what from status + VIP only; the retirement flag is a read-only view (#162 W5.1/W6.5)")
def test_bot_distribution_and_review_flag():
    """#162 W5.1 + W6.5 (migration 437, agreed with #155: #162 builds the views, #155 wires them).
    bot_distribution derives distribution ONLY from status + VIP (owner policy §3.1): VIP is a channel
    (never sent_public, never in the headline), experimental is admin-only, retired is on nothing; the
    *_drift columns name today's disagreements with show_on_performance / show_on_picks / hide_pending.
    bot_review_flag is the §3.3 flag (≥ 50 settled legs with sharp-anchor CLV AND the upper 95% bound < 0),
    active bots only, a FLAG — nothing reads it to retire anything. Both views are private."""
    mig = _engine_path("supabase/migrations/437_bot_distribution_and_review_flag.sql").read_text(encoding="utf-8")
    assert "CREATE OR REPLACE VIEW public.bot_distribution" in mig and "CREATE OR REPLACE VIEW public.bot_review_flag" in mig
    assert "REVOKE ALL ON public.bot_distribution, public.bot_review_flag FROM PUBLIC, anon, authenticated" in mig
    assert "SELECT 50 AS min_n" in mig and "(u.clv_n >= k.min_n AND u.clv_public_upper95 < 0)" in mig
    assert "(d.public_status AND d.vip)                                            AS vip_channel" in mig, \
        "VIP is a channel on top of a PUBLIC status — VIP · EXPERIMENTAL sends nothing"
    from workers.api_clients.db import execute_query
    try:
        applied = execute_query("SELECT to_regclass('public.bot_review_flag') IS NOT NULL AS ok")[0]["ok"]
    except Exception:  # noqa: BLE001 — no DB in this environment
        return
    if not applied:          # migrations apply in parallel with CI; a real breakage still fails below
        return
    if True:
        bad = execute_query("""SELECT
              count(*) FILTER (WHERE vip AND (sent_public OR in_headline OR pending_public)) AS vip_public,
              count(*) FILTER (WHERE status = 'retired' AND (on_performance OR sent_public OR vip_channel)) AS retired_on,
              count(*) FILTER (WHERE status = 'experimental' AND (on_performance OR sent_public OR vip_channel)) AS exp_public
            FROM bot_distribution""")[0]
        flag_retired = execute_query("""SELECT count(*) AS n FROM bot_review_flag f JOIN bots b ON b.name = f.bot_name
                                         WHERE b.retired_at IS NOT NULL OR NOT b.is_active""")[0]["n"]
        anon = execute_query("SELECT has_table_privilege('anon','bot_distribution','SELECT') a, "
                             "has_table_privilege('anon','bot_review_flag','SELECT') b")[0]
        no_basis = execute_query("SELECT count(*) AS n FROM bot_review_flag WHERE clv_n_public = 0 AND reason <> 'no_clv_basis'")[0]["n"]
    assert bad == {"vip_public": 0, "retired_on": 0, "exp_public": 0}, bad
    assert no_basis == 0, "a bot with no CLV basis must say so, not read as a silent 'not flagged'"
    assert flag_retired == 0, "the flag covers active bots only"
    assert anon == {"a": False, "b": False}, anon


