@test("VIP-FIRST-HOLD-BACK — #164: ONE guard holds free picks back until kickoff when VIP holds (or would take) them")
def test_vip_first_hold_back():
    """[[#164]] VIP FIRST (owner 2026-09-25). VIP bots never give up a pick. A FREE pick that a VIP /
    hide_pending bot holds (the ledger), or that is in VIP's range at its price and decision time, is
    RECORDED but held back — held_back_until = kickoff — and every public surface filters on that
    column. Pins: (1) ONE module decides, and every writer calls it (store_bet, the forward-test claim,
    the /picks board); (2) the re-derived pipeline `vip_exclude` is gone; (3) VIP's O/U rule is ONE
    function used by the VIP bot and the guard; (4) every public surface filters the data (views, anon
    policy, signaler, web pending views); (5) BEHAVIOUR in a rolled-back txn: a free pick written before
    a VIP pick on the same selection is held back by the VIP write, is absent from picks_public_all and
    picks_forward_test_public before kickoff, and appears after kickoff."""
    import inspect
    from workers.utils import vip_guard as g
    from workers.jobs import ou_sharp_outlier as ou
    # (1) one decision, every writer
    sb = _engine_path("workers/api_clients/supabase_client.py").read_text(encoding="utf-8")
    body = sb[sb.index("def store_bet("):sb.index("def bulk_store_shadow_bets(")]
    assert "from workers.utils.vip_guard import hold_back_fields" in body
    assert body.index("hold_back_fields(") < body.index("INSERT INTO simulated_bets"), "stamped IN the insert"
    assert "hold_back_followers(" in body and body.index("INSERT INTO simulated_bets") < body.index("hold_back_followers(")
    pub = _engine_path("scripts/publish_picks_forward_test.py").read_text(encoding="utf-8")
    claim = pub[pub.index("def claim("):pub.index("def attach_message_id(")]
    assert "from workers.utils.vip_guard import is_held_back" in claim and "held_back_until, held_back_reason)" in claim
    assert "if arm in PUBLISHED_ARMS:" in claim
    board = pub[pub.index("def write_board("):pub.index("def _break_even(")]
    assert "is_held_back(" in board and "held_back_until = COALESCE(picks_board.held_back_until" in board
    main = pub[pub.index("def main("):]
    assert 'if c.get("held_back_reason"):' in main
    sched = _engine_path("workers/scheduler.py").read_text(encoding="utf-8")
    job = sched[sched.index("def job_publish_picks_forward_test"):sched.index("def _publish_picks_forward_test_wrapper")]
    # #162 W5.3: the two loop guards (the unsent-recorder also reads the reason, for pick_sends)
    assert job.count('paused or c.get("held_back_reason")') == 2, "both published arms' send loops skip held-back picks"
    # no second copy of the rule anywhere in workers/ or scripts/ (the guard is the only reader of
    # rating_1x2 NEW+ for a hold-back decision, and nobody else writes held_back_until)
    for f in list(_engine_root.joinpath("workers").rglob("*.py")) + list(_engine_root.joinpath("scripts").glob("*.py")):
        rel = str(f.relative_to(_engine_root))
        txt = f.read_text(encoding="utf-8", errors="ignore")
        if rel in ("workers/utils/vip_guard.py", "scripts/smoke_test.py"):
            continue
        assert "SET held_back_until" not in txt, f"{rel} writes held_back_until outside vip_guard"
        assert 'config.get("vip_exclude")' not in txt, f"{rel} re-derives the VIP rule (vip_exclude)"
    # (2) the pipeline no longer re-derives or skips
    pipe = _engine_path("workers/jobs/daily_pipeline_v2.py").read_text(encoding="utf-8")
    assert '"vip_exclude"' not in pipe.split("# [[#164]] no `vip_exclude`")[0][-3000:] and "drop_vip_held" not in pipe
    # (3) VIP's O/U rule: one function, used by both
    # #162 W7.6 (2026-09-26): evaluate() runs the sharp engine on _rules() and early_rule() is the engine's
    # gate stack on the SAME EARLY rule — still one definition for both (was: evaluate called early_rule).
    ev_src = inspect.getsource(ou.evaluate)
    assert "_rules()" in ev_src and "price_refusal(_rules()[0]" in inspect.getsource(ou.early_rule)
    assert "ou.early_rule(odds, p, hours)" in inspect.getsource(g.in_vip_range)
    assert ou.early_rule(2.00, 0.55, 13.0) and not ou.early_rule(2.00, 0.55, 11.9)
    assert not ou.early_rule(2.00, 0.60, 20.0), "EV 20% is above the 15% cap (misposted line)"
    assert not ou.early_rule(1.25, 0.90, 20.0), "below VIP's odds floor"
    # 1X2 range reads the EV5 bot's OWN config (never a copied constant)
    from workers.jobs.daily_pipeline_v2 import BOTS_CONFIG
    assert g._vip_1x2_rule() == (BOTS_CONFIG[g.VIP_1X2_BOT]["edge_thresholds"][1]["1x2_fav"],
                                 *BOTS_CONFIG[g.VIP_1X2_BOT]["odds_range"])
    from workers.registry.bot_registry import VIP_BOTS
    assert g.VIP_1X2_BOT in VIP_BOTS
    # fails CLOSED
    orig = g.vip_held
    try:
        g.vip_held = lambda *a: (_ for _ in ()).throw(RuntimeError("boom"))
        from datetime import datetime, timedelta, timezone
        r, _ = g.is_held_back("00000000-0000-0000-0000-000000000000", "1x2", "home", 2.0,
                              kickoff=datetime.now(timezone.utc) + timedelta(hours=5))
        assert r == g.REASON_ERROR, "an evaluation failure must hold the pick back"
    finally:
        g.vip_held = orig
    # (4) every public surface filters the stored data
    mig = _engine_path("supabase/migrations/439_vip_first_hold_back.sql").read_text(encoding="utf-8")
    for v in ("picks_public_all", "picks_board_public", "picks_forward_test_public", "bot_ledger_display"):
        assert f"CREATE OR REPLACE VIEW {v} AS" in mig, v
    assert mig.count("NOT COALESCE(p.held_back_until > now(), false)") == 2
    assert "NOT COALESCE(s.held_back_until > now(), false)" in mig and "NOT COALESCE(b.held_back_until > now(), false)" in mig
    assert 'CREATE POLICY "Public read" ON simulated_bets' in mig and "AND NOT COALESCE(held_back_until > now(), false))" in mig
    sig = _engine_path("workers/automation/coolbet_signaler.py").read_text(encoding="utf-8")
    assert "COALESCE(bool_or(sb.held_back_until > NOW())" in sig and "WHERE NOT q.group_held_back" in sig
    try:
        web = _web_path("src/lib/bot-performance.ts").read_text(encoding="utf-8")
        assert "held_back\";" in web and web.count(".filter(isVisibleLeg)") == 2
        route = _web_path("src/app/api/performance/bot-legs/route.ts").read_text(encoding="utf-8")
        # [[#155]] experimental bots are simply not listed (status alone), so no settled-only special case
        assert "isPublicBot(b.maturityLabel)" in route and "settledOnly: isVipBot(b) || b.hidePending" in route
    except SkipTest:
        pass
    # (5) behaviour, rolled back
    import workers.api_clients.db as dbm
    try:
        with module_db_txn(dbm) as cur:
            home, away, league = _fixture_ids(cur)
            cur.execute("""INSERT INTO matches (date, home_team_id, away_team_id, league_id, season, status)
                           VALUES (now() + interval '20 hours', %s, %s, %s, 2026, 'scheduled') RETURNING id""",
                        (home, away, league))
            mid = cur.fetchone()[0]
            cur.execute("SELECT id FROM bots WHERE name = 'bot_v10_1x2'")
            free_bot = cur.fetchone()[0]
            cur.execute("SELECT id FROM bots WHERE name = %s", (g.VIP_1X2_BOT,))
            vip_bot = cur.fetchone()[0]
            ins = """INSERT INTO simulated_bets (bot_id, match_id, market, selection, odds_at_pick, pick_time,
                                                 stake, model_probability, edge_percent, result, reasoning)
                     VALUES (%s, %s, '1x2', 'home', 2.10, now(), 10, 0.52, 0.04, 'pending', 'smoke #164')
                     RETURNING id"""
            cur.execute(ins, (free_bot, mid)); free_id = cur.fetchone()[0]
            cur.execute("""INSERT INTO picks_forward_test (match_id, market, selection, odds, bookmaker, edge,
                             p_sharp, anchor_odds, anchor_quoted_at, odds_quoted_at, alignment_gap_minutes,
                             arm, rule_version, kickoff_at)
                           VALUES (%s, '1x2', 'home', 2.10, 'Bet365', 0.04, 0.50, '{}'::jsonb, now(), now(), 0,
                                   'consensus_anchor', 'smoke', now() + interval '20 hours') RETURNING id""", (mid,))
            ft_id = cur.fetchone()[0]
            def visible(view, pid):
                cur.execute(f"SELECT count(*) FROM {view} WHERE id = %s", (pid,))
                return cur.fetchone()[0] == 1
            assert visible("picks_public_all", free_id) and visible("picks_forward_test_public", ft_id), \
                "fixture must start visible"
            # the VIP pick lands AFTER the free ones — VIP never gives it up
            cur.execute(ins, (vip_bot, mid))
            assert g.vip_held(str(mid), "1x2", "home")
            got = g.hold_back_followers(str(mid), "1x2", "home")
            assert got == {"simulated_bets": 1, "picks_forward_test": 1}, got
            cur.execute("SELECT held_back_reason, held_back_until = (SELECT date FROM matches WHERE id = %s) "
                        "FROM simulated_bets WHERE id = %s", (mid, free_id))
            assert cur.fetchone() == (g.REASON_HELD, True), "held until KICKOFF, reason recorded"
            assert not visible("picks_public_all", free_id), "a VIP-held free pick must not be on /picks before kickoff"
            assert not visible("picks_public_all", ft_id) and not visible("picks_forward_test_public", ft_id)
            # a NEW free pick on the same selection is held back at write time
            reason, ko = g.is_held_back(str(mid), "1x2", "home", 2.05)
            assert reason == g.REASON_HELD and ko is not None
            # the VIP bot's own pick is never "held back" — it is the protected pick
            assert g.hold_back_fields(str(vip_bot), str(mid), "1x2", "home", 2.10) == {}
            # after kickoff it simply appears (and nothing is held any more)
            cur.execute("UPDATE matches SET date = now() - interval '1 minute' WHERE id = %s", (mid,))
            cur.execute("UPDATE simulated_bets SET held_back_until = now() - interval '1 minute' WHERE id = %s", (free_id,))
            cur.execute("UPDATE picks_forward_test SET held_back_until = now() - interval '1 minute', "
                        "kickoff_at = now() - interval '1 minute' WHERE id = %s", (ft_id,))
            assert visible("picks_public_all", free_id) and visible("picks_forward_test_public", ft_id)
            assert g.is_held_back(str(mid), "1x2", "home", 2.05)[0] is None, "after kickoff nothing is held"
    except SkipTest:
        raise
    except Exception as e:                       # noqa: BLE001
        if "could not connect" in str(e).lower() or "connection" in str(e).lower():
            raise SkipTest(f"DB not reachable: {e}")
        raise



@test("CLV-AUTOVOID-STICKS — an autovoid is a quarantine, so the resettle pass can no longer undo it (#162 W1.1/W1.2)")
def test_clv_autovoid_sticks():
    """#162 W1.1/W1.2 (owner decisions 1C + 5A, 2026-09-25). CLV-AUTOVOID voided bets whose pick price was
    ≥ 1.65× the close (a data error) but wrote no void_reason; resettle_wrongly_voided_bets re-grades every
    void whose reason is not a quarantine, so 90 of 93 came back graded (net +591 paper). The autovoid now
    writes void_reason 'quarantine: clv-autovoid — …' (which resettle skips) and no longer excludes rows it
    tagged before, so a re-graded row is RE-JUDGED on today's corrected close. Live invariant: no settled
    won/lost simulated bet fails the 1.65× test (checked after the first run of the new step)."""
    st = _engine_path("workers/jobs/settlement.py").read_text(encoding="utf-8")
    fn = st[st.index("def _apply_clv_autovoid("):]
    fn = fn[:fn.index("RETURNING id")]
    assert "void_reason = 'quarantine: clv-autovoid" in fn, "the autovoid must record a quarantine reason"
    assert "LEAST(odds_at_pick, COALESCE(odds_at_pick_live, odds_at_pick)) / closing_odds" in fn, "judged at the lower of recorded and executable"
    assert "AND (reasoning IS NULL OR reasoning NOT LIKE" not in fn, "tagged-then-regraded rows must be re-judged"
    assert "LEFT(sb.void_reason, 10) <> 'quarantine'" in st, "resettle must keep skipping quarantines"
    # review 2026-09-25: the paper bankroll moves with the void in the SAME statement (BOT-BANKROLL-DRIFT),
    # and the step also runs in the 15-minute settle pass, not only the evening run_settlement
    assert "UPDATE bots b" in fn and "current_bankroll = b.current_bankroll - d.removed" in fn
    rd = st[st.index("def settle_ready_matches("):]
    rd = rd[:rd.index("def resettle_wrongly_voided_bets(")]
    assert rd.index("_apply_clv_autovoid()") < rd.index("resettle_wrongly_voided_bets()")
    from workers.api_clients.db import execute_query
    try:
        n = execute_query("""SELECT (SELECT count(*) FROM simulated_bets
                              WHERE result IN ('won','lost') AND closing_odds > 0
                                AND settled_at < now() - interval '30 minutes'
                                AND LEAST(odds_at_pick, COALESCE(odds_at_pick_live, odds_at_pick)) / closing_odds >= 1.65)
                           + (SELECT count(*) FROM shadow_bets   -- #162 W1.5: the same rule on shadow picks
                              WHERE result IN ('won','lost') AND closing_odds > 0
                                AND LEAST(odds_at_pick, COALESCE(odds_at_pick_live, odds_at_pick)) / closing_odds >= 1.65
                                AND pick_time < now() - interval '1 day') AS n""")[0]["n"]
    except Exception:  # noqa: BLE001 — no DB here
        return
    assert n == 0, f"{n} settled bet(s) fail the 1.65x data-error test — the autovoid step did not run or was undone"


@test("REAL-BETS-PAPER-NEVER-COUNTED — proven-paper real_bets rows are labelled paper, proven-real rows real (#162 W4.1)")
def test_real_bets_paper_never_counted():
    """#162 W4.1 (migration 440, owner decision 2C). 849 real_bets rows had no paper/real state, so every money
    page (placed_real IS NOT FALSE) counted €3k+ of never-placed paper stake as real. The provably-paper
    classes (ticket=None after 2026-05-23 08:00, in-play and combo executors that never POSTed) are FALSE;
    ticket-evidenced rows are TRUE; everything else stays NULL (unverified) for the owner's statement check.
    Live invariant: none of the provably-paper patterns is left NULL, and no ticketed auto row is paper."""
    mig = _engine_path("supabase/migrations/440_real_bets_placed_real_backfill.sql").read_text(encoding="utf-8")
    assert "placed_at >= '2026-05-23 08:00+00'" in mig, "DUPE-FIX-2 cutoff: 07:17–07:23 rows are failed real attempts"
    assert "IF n <> 379 THEN" in mig and "IF n <> 352 THEN" in mig
    assert "notes IS NULL AND placed_at >= '2026-06-08'" not in mig, "no-note June rows are NOT provably paper"
    from workers.api_clients.db import execute_query
    try:
        applied = execute_query("SELECT count(*) AS n FROM _schema_migrations WHERE filename LIKE '440%%'")[0]["n"]
    except Exception:  # noqa: BLE001 — no DB here
        return
    if not applied:
        return
    r = execute_query("""SELECT
          count(*) FILTER (WHERE placed_real IS NULL AND (notes LIKE 'inplay-auto%%' OR notes LIKE 'auto-combo%%'
                                OR (notes LIKE 'auto ticket=None%%' AND placed_at >= '2026-05-23 08:00+00'
                                    AND placed_at < '2026-09-25'))) AS paper_left_null,
          count(*) FILTER (WHERE placed_real IS NOT TRUE AND notes ~ '^auto ticket=[0-9]') AS real_not_true
        FROM real_bets""")[0]
    assert r == {"paper_left_null": 0, "real_not_true": 0}, r


@test("PAPER-WRITERS-KEEP-FIRST-PRICE — a shadow pick's recorded price is the one at pick time, never rewritten (#162 W2.1)")
def test_paper_writers_keep_first_price():
    """#162 W2.1 (owner 11A, 2026-09-25). pick_generator and the trigger matcher upserted shadow_bets with
    DO UPDATE on every sweep: price/prob/edge rewritten, pick_time kept — 22-52% of their rows carried a price
    1.0-3.8% above the quote at pick time (audit A §2). The first write is now the pick (DO NOTHING), and
    odds_at_pick_live is left NULL for workers/utils/pick_price.py (#159) to fill with the pick-time own and
    public prices (it only fills NULLs, so a writer's single-book value pre-empted it)."""
    for f in ("workers/automation/pick_generator.py", "workers/jobs/pick_trigger_matcher.py",
              "workers/jobs/ou35_model_shadow.py"):
        src = _engine_path(f).read_text(encoding="utf-8")
        ins = src[src.index("INSERT INTO shadow_bets"):]
        ins = ins[:ins.index('""",')]
        assert "ON CONFLICT (shadow_cohort, bot_id, match_id, market, selection) DO NOTHING" in ins, f
        assert "DO UPDATE SET" not in ins, f
        # odds_at_pick_live = this bot's OWN-book price at the decision (review: #159's backfill would store
        # the MAX across all four Estonian books — a price a single-book bot could not take)
        assert "%s,%s, now()" in ins, f"{f}: odds_at_pick_live must be the own-book price at insert"


@test("SPENT-TODAY-ALL-BOOKS — the daily cap counts every book and every placed or unverified stake (#162 W4.2)")
def test_spent_today_all_books():
    """#162 W4.2 (owner 3C, 2026-09-25). spent_today() — the runaway backstop behind MAX_BETS_PER_DAY /
    MAX_STAKE_PER_DAY for BOTH the UI placer and the router — counted Coolbet only, so Unibet stakes and
    manual / unverified real bets never counted. It now counts every placed attempt (even if its real_bets
    write failed) plus every real_bets row today at ANY book with placed_real IS NOT FALSE, de-duplicated on
    real_bet_id. Only tightens: measured over 30 days, the new count is >= the old one every day."""
    import inspect
    import scripts.place_coolbet_ui as ui
    src = inspect.getsource(ui.spent_today)
    assert "rb.placed_real IS NOT FALSE" in src and "bookmaker = 'Coolbet'" not in src
    assert "pa.real_bet_id = rb.id AND pa.outcome = 'placed'" in src, "de-duplicated on real_bet_id"
    from workers.api_clients.db import execute_query
    try:
        r = execute_query("""
            WITH d AS (SELECT generate_series(date_trunc('day', now()) - interval '14 days',
                                              date_trunc('day', now()), interval '1 day') AS d)
            SELECT count(*) FILTER (WHERE new_n < old_n) AS looser FROM (
              SELECT (SELECT count(*) FROM coolbet_placement_attempts WHERE outcome='placed'
                        AND attempted_at >= d.d AND attempted_at < d.d + interval '1 day')
                   + (SELECT count(*) FROM real_bets WHERE bookmaker='Coolbet' AND placed_real IS TRUE
                        AND notes LIKE 'auto ticket=%%' AND placed_at >= d.d AND placed_at < d.d + interval '1 day') AS old_n,
                     (SELECT count(*) FROM coolbet_placement_attempts WHERE outcome='placed'
                        AND attempted_at >= d.d AND attempted_at < d.d + interval '1 day')
                   + (SELECT count(*) FROM real_bets rb WHERE placed_at >= d.d AND placed_at < d.d + interval '1 day'
                        AND placed_real IS NOT FALSE AND NOT EXISTS (SELECT 1 FROM coolbet_placement_attempts pa
                        WHERE pa.real_bet_id = rb.id AND pa.outcome = 'placed')) AS new_n
                FROM d) x""")[0]
    except Exception:  # noqa: BLE001 — no DB here
        return
    assert r["looser"] == 0, "the new daily count must never be below the old one"


@test("ROUTER-RUN-LOCK — the best-price router refuses a real/stage run while another pass holds the placer lock (#162 W4.2)")
def test_router_run_lock():
    """#162 W4.2 (2026-09-25). The router had no run lock, so it and place_coolbet_ui could drive the same
    browser and read the same "spent today" concurrently. route(execute|stage) now takes the SAME flock
    (~/.coolbet-daemon/ui-placer.lock); a busy lock returns aborted without dispatching anything."""
    import workers.automation.best_price_router as br
    import scripts.place_coolbet_ui as ui
    called = []
    with _ROUTER_ENV_LOCK:                          # the other route(execute=True) tests take the same flock
        o_r = br._route
        try:
            br._route = lambda *a, **k: (called.append(1) or {"mode": "real", "aborted": None})
            with ui.single_run_lock():
                out = br.route(execute=True)
            assert called == [] and "run lock busy" in (out.get("aborted") or ""), out
            assert out["mode"] == "report" and out.get("real_refused"), "a refused run must not read as real"
            out = br.route(execute=False)           # a plain report takes no lock
            assert called == [1], called
        finally:
            br._route = o_r


