@test("FLAT-STAKES-EVERYWHERE — every bot stakes one flat unit; stored pnl is the published flat pnl (#155)")
def test_flat_stakes_everywhere():
    """[[#155]] owner 2026-09-25: "keep flat stakes everywhere, Kelly hasn't proven itself in this project
    yet". compute_stake returns FLAT_STAKE_EUR (or 0 when the pick fails the UNCHANGED minimum-Kelly
    selection gate — kept so no live bot's pick set changes); the 3rd-pick-per-league halving is gone;
    in-play stakes the unit; settlement computes simulated_bets.pnl at the PUBLIC price (the rule of
    bot_ledger.odds_public), so stored pnl == what /performance publishes. Migration 441 restated every
    existing row (original stake in stake_kelly_original) and a trigger coerces any non-flat stake."""
    import inspect
    from workers.model import improvements as imp
    assert imp.FLAT_STAKE_EUR == 10.0
    # sizing is flat; the eligibility gate is the old arithmetic, bit for bit
    def _legacy(k, br, t, pen):
        if k <= 0 or br <= 0:
            return 0.0
        st = min(k * 0.15 * br, 0.010 * br) * {"A": 1.0, "B": 0.5, "C": 0.25}.get(t, 0.5)
        st = st * (1 - pen) if pen > 0 else st
        return 0.0 if st < 1.0 else round(st, 2)
    for k in (0.0, 0.004, 0.007, 0.02, 0.1, 0.5):
        for br in (0.0, 150.0, 1000.0, 5000.0):
            for t in ("A", "B", "C", "?"):
                for pen in (0.0, 0.5, 0.8):
                    want = imp.FLAT_STAKE_EUR if _legacy(k, br, t, pen) > 0 else 0.0
                    assert imp.compute_stake(k, br, t, odds_penalty=pen) == want, (k, br, t, pen)
    from workers.jobs import daily_pipeline_v2 as dp
    src = inspect.getsource(dp)
    assert "stake * 0.5" not in src, "the league-exposure stake halving is retired (flat unit)"
    assert "not shadow_mode and _league_count >= 2" in src   # the count/report stays
    # #162 W7.2 (2026-09-26): the in-play builder (inplay_bot._build_inplay_bet_data) is deleted; no in-play stake is written.
    # the ONE public-price rule, same as bot_ledger (migration 433)
    from workers.utils.pick_price import public_price
    assert public_price({"odds_at_pick": 2.5, "odds_at_pick_live": 2.2, "odds_at_pick_available": 2.3}) == (2.3, "available")
    assert public_price({"odds_at_pick": 2.5, "odds_at_pick_live": 2.2, "odds_at_pick_available": None}) == (2.2, "our_books")
    assert public_price({"odds_at_pick": 2.5, "odds_at_pick_live": 1.0, "odds_at_pick_available": None}) == (2.5, "recorded")
    m433 = _engine_path("supabase/migrations/433_one_bot_performance.sql").read_text()
    assert ("CASE WHEN s.odds_at_pick_available > 1 THEN s.odds_at_pick_available\n"
            "             WHEN s.odds_at_pick_live > 1 THEN s.odds_at_pick_live ELSE s.odds_at_pick END AS odds_public") in m433
    from workers.jobs import settlement as st
    sp = inspect.getsource(st._settle_pending_bets)
    assert sp.count("price=public_price(bet)[0]") == 2 and "pnl_price_basis = %s" in sp
    assert "_price_before_settling(pending)" in sp, "price the legs BEFORE settling (else pnl lands on the recorded price)"
    won = st.settle_bet_result({"market": "1x2", "selection": "home", "stake": 10, "odds_at_pick": 3.0,
                                "match_id": None}, 2, 0, None, price=2.5)
    assert won["result"] == "won" and won["pnl"] == 15.0, won
    assert 'price=public_price(bet)[0] if table == "simulated_bets"' in inspect.getsource(st.resettle_wrongly_voided_bets), \
        "the void-integrity repair re-grades simulated_bets at the public price too"
    from workers.jobs import results_check as rc
    assert 'public_price(b)[0] if table == "simulated_bets"' in inspect.getsource(rc._regrade)
    m441 = _engine_path("supabase/migrations/441_flat_stakes_restatement.sql").read_text()
    assert "IF NEW.stake IS DISTINCT FROM 10 THEN" in m441 and "stake_kelly_original" in m441
    assert "real_bets" not in m441.split("BEGIN;", 1)[1], "real_bets is untouched"
    from workers.api_clients.db import execute_query
    have = execute_query("""SELECT 1 AS x FROM information_schema.columns
                             WHERE table_name = 'simulated_bets' AND column_name = 'stake_kelly_original'""", [])
    if not have:
        return "441 not applied yet — source pins only"
    r = execute_query("""SELECT count(*) FILTER (WHERE stake <> 10) AS nonflat,
                                count(*) FILTER (WHERE stake_kelly_original IS NULL) AS unpreserved,
                                (SELECT count(*) FROM pg_trigger WHERE tgname = 'simulated_bets_flat_stake') AS trg
                           FROM simulated_bets""", [])[0]
    assert r["nonflat"] == 0 and r["trg"] == 1, r
    basis = execute_query("""SELECT count(*) AS n FROM bot_ledger l JOIN simulated_bets s ON s.id = l.pick_id
                              WHERE l.source = 'sim' AND l.result IN ('won','lost')
                                AND s.pnl_price_basis IS DISTINCT FROM l.public_basis""", [])[0]["n"]
    assert basis == 0, f"{basis} settled legs whose pnl_price_basis differs from bot_ledger.public_basis"
    return "flat unit everywhere; stored pnl basis == public basis"


@test("SMOKE-NEW-VS-INHERITED — CI splits failures into NEW vs INHERITED, stays red on any; router tests run offline; migration race excused")
def test_smoke_new_vs_inherited():
    """Dev-process speed audit steps 1-3 (2026-09-25). (1) the runner diffs this run's failing names
    against the previous completed main run's artifact and never changes the exit code; (2) the three
    router tests that were the suite's critical path (309/262/261 s in CI) run on fixtures; (3)
    MIGRATION-EDITS-ARE-INVISIBLE no longer reads a NEWER push's migration as "missing from disk"."""
    import json, tempfile, os, inspect
    d = tempfile.mkdtemp()
    base, out = os.path.join(d, "b.json"), os.path.join(d, "o.json")
    with open(base, "w") as fh:
        json.dump({"sha": "prev", "failed": ["OLD-RED", "NOW-GREEN"], "first_red": {"OLD-RED": "sha0"}}, fh)
    results = [("OLD-RED", "fail", "x", 0.0), ("MINE", "fail", "y", 0.0), ("NOW-GREEN", "pass", "", 0.0)]
    _report_new_vs_inherited(results, out, base, quiet=True)
    r = json.load(open(out))
    assert r["new"] == ["MINE"] and r["inherited"] == ["OLD-RED"] and r["fixed"] == ["NOW-GREEN"], r
    assert r["first_red"]["OLD-RED"] == "sha0", "inherited failures keep the SHA they first went red at"
    _report_new_vs_inherited(results, out, os.path.join(d, "missing.json"), quiet=True)
    assert json.load(open(out))["new"] == ["MINE", "OLD-RED"], "no baseline → every failure is NEW, none dropped"
    src = inspect.getsource(main)
    assert "sys.exit(0 if failed == 0 else 1)" in src, "the split must never turn a red run green"

    wf = _engine_path(".github/workflows/smoke_tests.yml").read_text(encoding="utf-8")
    assert "--baseline _baseline/smoke_failures.json" in wf and "--failures-json smoke_failures.json" in wf
    assert "name: smoke-failures" in wf and "if: always()" in wf, "a red run must still publish its list"
    assert "actions: read" in wf and "continue-on-error: true" in wf, "baseline fetch must never fail the job"

    for fn in (test_best_price_router_execute_wiring, test_router_no_allowlist_bypass):
        assert "_router_offline(" in inspect.getsource(fn), f"{fn.__name__} must run route() on fixtures"
    assert "_this_thread_only(" in inspect.getsource(test_gate_status_reads_the_same_env)

    mig = inspect.getsource(test_migration_edits_are_invisible)
    assert "_newer_than_checkout" in mig and "%ct" in mig, "applied-after-this-commit migrations must be excused"


@test("VERIFY-QUEUE — ops/verify/*.yml parse, checks run read-only, state machine alerts once, job scheduled")
def test_verify_queue():
    """#168a (2026-09-25). Tasks hand off post-deploy checks as ops/verify/<task>.yml (or a
    migration `-- verify:` line) and the scheduler's verify_queue job runs them when due — so no
    agent waits for a deploy. This pins: every committed spec parses (a malformed file would sit
    silently unrun); only a single SELECT/WITH is accepted and the session is read-only; the
    state machine (now / eventually / invariant) alerts once per transition, and expiry fires."""
    import inspect
    from datetime import datetime, timedelta, timezone
    from workers.jobs import verify_queue as vq

    specs = vq.load_yaml_specs()
    assert len(specs) >= 5, f"seed checks missing: {len(specs)}"
    assert len({s["check_id"] for s in specs}) == len(specs), "duplicate check ids"
    for bad in ("DELETE FROM bots", "SELECT 1; DELETE FROM bots", "UPDATE bots SET name='x'"):
        try:
            vq._check_sql(bad)
            raise AssertionError(f"accepted {bad!r}")
        except ValueError:
            pass
    assert "default_transaction_read_only=on" in inspect.getsource(vq._ro_connect)
    assert "statement_timeout" in inspect.getsource(vq._ro_connect)

    ev = vq.evaluate
    assert ev(3, ">= 1") and not ev(0, ">= 1") and ev(0, "== 0") and ev("t", "true")
    assert ev(True, "true") and not ev(None, "not null") and ev("abc", "== 'abc'") and not ev(None, "== 0")

    now = datetime(2026, 9, 25, 16, tzinfo=timezone.utc)
    base = {"check_id": "x::y", "task": "t", "source": "x", "name": "y", "sql": "SELECT 1", "cmd": None,
            "cmd_value": "stdout", "expect": "== 0", "run_after": {}, "expires": now + timedelta(hours=1)}
    bad = lambda s: 5  # noqa: E731
    good = lambda s: 0  # noqa: E731
    r = vq.decide({**base, "mode": "now"}, None, now, True, "", bad)
    assert r["status"] == "failed", r
    r2 = vq.decide({**base, "mode": "now"}, {**r, "alerted_status": "failed"}, now, True, "", bad)
    assert r2["alerted_status"] == "failed", "same failure must not re-alert"
    assert vq.decide({**base, "mode": "now"}, None, now, True, "", good)["status"] == "passed"
    assert vq.decide({**base, "mode": "eventually"}, None, now, True, "", bad)["status"] == "pending"
    inv = vq.decide({**base, "mode": "invariant"}, None, now, True, "", good)
    assert inv["status"] == "holding", "an invariant keeps being watched after it holds"
    late = now + timedelta(hours=2)
    assert vq.decide({**base, "mode": "invariant"}, inv, late, True, "", good)["status"] == "passed"
    assert vq.decide({**base, "mode": "eventually"}, None, late, True, "", bad)["status"] == "expired"
    nd = vq.decide({**base, "mode": "now"}, None, late, False, "migration 999 not applied", bad)
    assert nd["status"] == "expired" and "never became due" in nd["detail"], nd
    boom = vq.decide({**base, "mode": "now"}, None, now, True, "", lambda s: 1 / 0)
    assert boom["status"] == "error" and "ZeroDivisionError" in boom["detail"]
    edited = vq.decide({**base, "mode": "now", "expect": "== 5"}, {**r, "status": "passed"}, now, True, "", bad)
    assert edited["status"] == "passed" and edited["runs"] == 1, "an edited check starts over"

    applied = {"447_verify_results.sql": now}
    assert vq.is_due({**base, "run_after": {"migration": "447"}}, now, applied, lambda j, s: False)[0]
    assert not vq.is_due({**base, "run_after": {"migration": "999"}}, now, applied, lambda j, s: True)[0]
    assert not vq.is_due({**base, "run_after": {"job": "betting_refresh", "since": "2026-09-25T15:30:00Z"}},
                         now, applied, lambda j, s: False)[0]
    mig = vq.load_migration_specs(applied, now)
    assert any(m["check_id"].endswith("447_verify_results.sql::verify1") for m in mig), mig

    sched = _engine_path("workers/scheduler.py").read_text(encoding="utf-8")
    assert '_run_job("verify_queue", run_verify_queue)' in sched and 'id="verify_queue"' in sched
    assert "PyYAML" in _engine_path("requirements.txt").read_text(encoding="utf-8")
    wf = _engine_path(".github/workflows/migrate.yml").read_text(encoding="utf-8")
    assert "Run migration verify lines" in wf and "default_transaction_read_only=on" in wf
    assert "ops/verify/<task>.yml" in _engine_path("CLAUDE.md").read_text(encoding="utf-8")
    assert "verify_queue" in _engine_path("WORKFLOWS.md").read_text(encoding="utf-8")


# ── [[#155]] ONE STATUS DECIDES DISTRIBUTION ────────────────────────────────────────────────────

def _m442() -> str:
    return _engine_path("supabase/migrations/442_one_status_decides_distribution.sql").read_text()


@test("ONE-STATUS-DECIDES-DISTRIBUTION — /picks, Telegram, headline and /performance all derive from the bot's status (#155)")
def test_one_status_decides_distribution():
    """[[#155]] (owner 2026-09-25). One status per bot decides distribution; no second per-bot setting may
    drift from it. Parity across the four surfaces: (1) the SQL predicate bot_public_status and the view
    bot_distribution; (2) bots.show_on_picks / show_on_performance DERIVED by trigger (update against the
    status rejected); (3) picks_public_all + picks_forward_test_public gate on bot_distribution; (4) the
    engine senders (coolbet_signaler, the forward-test publisher) read bot_distribution; (5) the headline
    (settlement dashboard_cache + web HEADLINE_MATURITY_LABELS) is BETA/CALIBRATED minus VIP; (6) the web
    /performance filter is the status alone. Live DB: every bot's derived columns equal the view."""
    import re
    import inspect
    from workers.utils import bot_status as bs
    sql = _m442()
    # (1) one predicate — the Python sets equal the SQL literal
    m = re.search(r"bot_public_status\(p_label text, p_retired_at timestamptz\).*?IN \(([^)]*)\)", sql, re.S)
    assert m, "bot_public_status definition missing"
    assert {x.strip().strip("'") for x in m.group(1).split(",")} == set(bs.PUBLIC_STATUSES)
    assert bs.HEADLINE_STATUSES == {"beta", "calibrated"} and bs.HEADLINE_STATUSES < bs.PUBLIC_STATUSES
    assert "maturity_label IN ('beta','calibrated') AND NOT b.vip" in bs.HEADLINE_BOT_SQL
    # behaviour of the Python face
    assert bs.sends_public("testing") and bs.sends_public("beta") and bs.sends_public("calibrated")
    assert not bs.sends_public("experimental") and not bs.sends_public(None)
    assert not bs.sends_public("testing", vip=True), "VIP is a channel: never sent publicly"
    assert bs.on_performance("testing") and not bs.on_performance("testing", retired_at="2026-09-25")
    assert not bs.in_headline("testing") and not bs.in_headline("calibrated", vip=True) and bs.in_headline("beta")
    # (2) derived columns: trigger + rejection
    assert "CREATE TRIGGER bots_zz_derive_distribution BEFORE INSERT OR UPDATE ON bots" in sql
    assert "NEW.show_on_picks := v_picks;" in sql and "NEW.show_on_performance := v_pub;" in sql
    assert sql.count("RAISE EXCEPTION") >= 2
    # (3) public views gate on the view, and the forward-test arm→bot CASE matches forward_test_bot
    for view in ("CREATE OR REPLACE VIEW picks_public_all", "CREATE OR REPLACE VIEW picks_forward_test_public"):
        body = sql[sql.index(view):].split(";", 1)[0]
        assert "bot_distribution bd" in body and "COALESCE(bd.sent_public, false) OR p.telegram_message_id IS NOT NULL" in body, view
        assert "p.grade = 'D'::text AND p.telegram_message_id IS NULL" not in body, "the hard-coded grade-D rule is replaced by status"
    pa = sql[sql.index("CREATE OR REPLACE VIEW picks_public_all"):].split(";", 1)[0]
    assert "WHERE bd.sent_public" in pa and "b.show_on_picks" not in pa, "model branch must read the status, not the switch"
    for arm, mkt, grade in (("consensus_anchor", "1x2", "D"), ("consensus_anchor", "1x2", "C"),
                            ("consensus_anchor", "over_under_25", "B"), ("live", "over_under_25", None),
                            ("live", "1x2", None)):
        assert f"THEN '{bs.forward_test_bot(arm, mkt, grade)}'" in pa or bs.forward_test_bot(arm, mkt, grade) == "bot_sharp_1x2_v1"
    # (4) engine senders
    sig = _engine_path("workers/automation/coolbet_signaler.py").read_text()
    assert "JOIN bot_distribution bd ON bd.bot_name = b.name" in sig and "bool_or(bd.sent_public)" in sig
    assert "maturity_label = 'calibrated'" not in sig, "the old calibrated-only public gate must be gone"
    assert "bd.sent_public DESC, sb.edge_percent DESC" in sig, "a SENT bot's row must supply the message"
    sched = _engine_path("workers/scheduler.py").read_text()
    assert "sent_bots = load_sent_public_bots()" in sched
    assert 'not arm_bot_sends(c, "live", sent_bots)' in sched and "not arm_bot_sends(c, CONSENSUS_ARM, sent_bots)" in sched
    assert 'c.get("grade") == "D" or paused' not in sched
    import scripts.publish_picks_forward_test as pf
    assert "arm_bot_sends(c, \"live\", sent_bots)" in inspect.getsource(pf.main)
    sent = {"bot_sharp_1x2_v1", "bot_consensus_c_v1"}
    assert pf.arm_bot_sends({"market": "1x2"}, "live", sent)
    assert not pf.arm_bot_sends({"market": "over_under_25"}, "live", sent)
    assert pf.arm_bot_sends({"market": "1x2", "grade": "C"}, pf.CONSENSUS_ARM, sent)
    assert not pf.arm_bot_sends({"market": "1x2", "grade": "D"}, pf.CONSENSUS_ARM, sent)
    assert not pf.arm_bot_sends({"market": "1x2"}, "live", None), "unreadable status = send nothing"
    assert not pf.arm_bot_sends({"market": "1x2"}, "junk_anchor", sent | {"control_junk_anchor"})
    ebc = _engine_path("scripts/export_bot_config.py").read_text()
    assert 'sent = g != "D"' not in ebc and "sends_public(" in ebc
    # (5) headline
    st = _engine_path("workers/jobs/settlement.py").read_text()
    wdc = st[st.index("def write_dashboard_cache"):]
    wdc = wdc[:wdc.index("\ndef ", 10)]
    assert "maturity_label != 'experimental'" not in wdc, "headline must be BETA/CALIBRATED (not 'anything but experimental')"
    assert wdc.count("{_HEADLINE_BOT_SQL}") >= 5
    # (6) web (skipped when the sibling repo is absent)
    try:
        ts = _web_path("src/lib/bot-status.ts").read_text()
    except SkipTest:
        ts = None
    if ts is not None:
        pub = re.search(r"PUBLIC_STATUSES = \[([^\]]*)\]", ts).group(1)
        head = re.search(r"HEADLINE_STATUSES = \[([^\]]*)\]", ts).group(1)
        assert {x.strip().strip('"') for x in pub.split(",")} == set(bs.PUBLIC_STATUSES)
        assert {x.strip().strip('"') for x in head.split(",")} == set(bs.HEADLINE_STATUSES)
        ed = _web_path("src/lib/engine-data.ts").read_text()
        assert "export const HEADLINE_MATURITY_LABELS = HEADLINE_STATUSES;" in ed
