@test("PERFORMANCE-RETIRED-PARITY — /performance work done + retired families read bot_performance; active headline excludes retired (#157)")
def test_performance_retired_parity():
    """[[#157]] owner 2026-09-25: /performance shows the work done (every strategy ever scored,
    retired included) WITHOUT making the active ROI dishonest. Three separate things: the headline
    (BETA + CALIBRATED, retired_at IS NULL — unchanged), bot_public_work_done (totals), and a
    collapsed retired section (bot_public_record_group families + bot_public_record representatives,
    migration 446). Every ROI/CLV there must be bot_performance's (#159) — a family is a SUM of its
    bots' rows, never a second ROI path. Also pins the in-play price fix found on the way: an in-play
    leg is priced at its recorded in-play odds (basis 'inplay'), never a pre-match quote (§14)."""
    mig = _engine_path("supabase/migrations/446_bot_public_record.sql").read_text()
    for v in ("bot_public_record", "bot_public_record_group", "bot_public_work_done"):
        assert f"CREATE OR REPLACE VIEW public.{v} AS" in mig, v
    assert "FROM bot_performance p" in mig, "the per-bot record must be bot_performance's rows"
    assert "sum(pnl_units_public) / sum(settled)" in mig, "family ROI = sum of the bots' public pnl / settled"
    assert "TO anon" not in mig, "private views only (#072)"
    rep = mig[mig.index("rep AS ("):mig.index("SELECT r.bot_name, r.display_name")]
    assert "roi_public" not in rep and "clv_public" not in rep.replace("clv_n", ""), \
        "representatives are chosen by sample + close coverage, never by result"
    assert "WHEN ip.inplay THEN s.odds_at_pick" in mig and "WHEN sh.inplay_minute IS NOT NULL THEN sh.odds_at_pick" in mig
    from workers.utils.pick_price import public_price
    assert public_price({"odds_at_pick": 2.5, "odds_at_pick_live": 1.7, "odds_at_pick_available": 1.8,
                         "match_minute_at_pick": 35}) == (2.5, "inplay")
    # web: the headline cohort never includes a retired bot; the work-done section is separate
    ed = _web_path("src/lib/engine-data.ts").read_text()
    coh = ed[ed.index("export async function getPublicCohortBotNames"):][:700]
    assert '.is("retired_at", null)' in coh, "the active headline must exclude retired bots"
    lib = _web_path("src/lib/performance-work-done.ts").read_text()
    for v in ("bot_public_work_done", "bot_public_record_group", "bot_public_record"):
        assert f'.from("{v}")' in lib, v
    assert "roi_public" in lib and "pnl_unit_public" not in lib and "bot_ledger" not in lib, \
        "the retired section reads the view's ROI, computes none from legs"
    page = _web_path("src/app/(app)/performance/page.tsx").read_text()
    assert "getWorkDone()" in page and "<PerformanceWorkDone" in page
    assert "getWorkDone" not in _web_path("src/lib/engine-data.ts").read_text(), "work done must not feed the headline"
    from workers.api_clients.db import execute_query
    if not execute_query("SELECT to_regclass('public.bot_public_record') AS r", [])[0]["r"]:
        return "446 not applied yet — source pins only"
    bad = execute_query("""
        SELECT r.bot_name FROM bot_public_record r JOIN bot_performance p USING (bot_name)
         WHERE r.roi_public IS DISTINCT FROM p.roi_public OR r.settled <> p.settled
            OR r.clv_public IS DISTINCT FROM p.clv_public OR r.pnl_units_public <> p.pnl_units_public""", [])
    assert not bad, f"bot_public_record differs from bot_performance: {bad}"
    fam = execute_query("""
        WITH s AS (SELECT r.public_group, sum(p.settled) st, sum(p.pnl_units_public) pnl, sum(p.picks_total) pk
                     FROM bot_public_record r JOIN bot_performance p USING (bot_name)
                    WHERE r.is_retired GROUP BY 1)
        SELECT g.public_group FROM bot_public_record_group g JOIN s USING (public_group)
         WHERE g.is_retired AND (g.settled <> s.st OR g.picks_total <> s.pk
               OR abs(g.pnl_units_public - s.pnl) > 1e-6
               OR abs(coalesce(g.roi_public, 0) - coalesce(round(s.pnl / nullif(s.st, 0), 6), 0)) > 1e-6)""", [])
    assert not fam, f"retired family rows are not the sum of their bots' bot_performance rows: {fam}"
    w = execute_query("""SELECT (SELECT picks_total FROM bot_public_work_done) AS w,
                                (SELECT sum(picks_total) FROM bot_performance) AS p,
                                (SELECT strategies FROM bot_public_work_done) AS ws,
                                (SELECT count(*) FROM bot_performance) AS ps""", [])[0]
    assert w["w"] == w["p"] and w["ws"] == w["ps"], f"work done != every bot_performance row: {w}"
    ip = execute_query("""SELECT count(*) AS n FROM bot_ledger WHERE is_inplay AND public_basis <> 'inplay'
                           AND source IN ('sim', 'shadow')""", [])[0]["n"]
    assert ip == 0, f"{ip} in-play legs priced off a pre-match quote"
    return f"{w['ws']} strategies / {w['w']} picks; retired families == sum of bot_performance; in-play priced in-play"



@test("SQL-COMMENT-PERCENT — every parameterised SQL string in the bot writers formats with its own placeholders")
def test_sql_comment_percent():
    """2026-09-25: a bare '%' inside a `--` comment of a parameterised psycopg2 SQL string is read as a format
    directive ("22-52% of", then "3.8% above" — '% a' is a valid conversion that eats an argument). Every
    pick_generator write raised from ~15:25 UTC until fixed (85202b04 + the follow-up). psycopg2 formats the
    WHOLE string, comments included, so write 'per cent' or '%%' in SQL comments. This formats each string with
    dummy params the way psycopg2 does and fails on any mismatch."""
    import re
    files = ("workers/automation/pick_generator.py", "workers/jobs/pick_trigger_matcher.py",
             "workers/jobs/ou35_model_shadow.py", "workers/jobs/pick_triggers.py", "workers/jobs/settlement.py",
             "scripts/place_coolbet_ui.py", "workers/jobs/clv_sharp.py", "workers/automation/best_price_router.py",
             "workers/automation/coolbet_placer.py", "workers/jobs/daily_pipeline_v2.py")
    bad = []
    for f in files:
        src = _engine_path(f).read_text(encoding="utf-8")
        for m in re.finditer(r'"""(.*?)"""', src, re.S):
            body = m.group(1)
            if not re.search(r"\b(SELECT|UPDATE|INSERT|WITH)\b", body):
                continue
            named = re.findall(r"%\((\w+)\)s", body)
            n = body.count("%s")
            if not named and n == 0:
                continue
            try:
                body % ({k: "x" for k in named} if named else tuple(["x"] * n))
            except Exception as e:  # noqa: BLE001
                bad.append(f"{f}:{src[:m.start()].count(chr(10)) + 1} {type(e).__name__}: {e}")
    assert not bad, "SQL strings that psycopg2 cannot format (a bare % in a comment?):\n" + "\n".join(bad)


@test("SETTLE-INPLAY-PUBLIC-PRICE — settlement loads the in-play markers public_price() needs (#162, the #157 leftover)")
def test_settle_inplay_public_price():
    """#157 (migration 446) priced in-play paper legs at their own in-play odds in bot_ledger, and
    pick_price.public_price() does the same — IF the row carries match_minute_at_pick / xg_source. Neither
    settlement read loaded them, so settling or re-grading an in-play simulated leg priced its pnl at a
    PRE-MATCH quote (a different market, ANALYSIS_GOTCHAS §14)."""
    from workers.jobs import settlement as st
    from workers.utils.pick_price import public_price
    src = _engine_path("workers/jobs/settlement.py").read_text(encoding="utf-8")
    assert "sb.match_minute_at_pick, sb.xg_source," in src
    assert 'inplay_cols="sb.match_minute_at_pick, sb.xg_source," if table == "simulated_bets" else ""' in src
    sim = st._WRONGLY_VOIDED_SQL.format(table="simulated_bets", inplay_cols="sb.match_minute_at_pick, sb.xg_source,")
    assert "sb.match_minute_at_pick" in sim
    rc = _engine_path("workers/jobs/results_check.py").read_text(encoding="utf-8")
    assert 'cols = ", b.match_minute_at_pick, b.xg_source" if table == "simulated_bets" else ""' in rc, \
        "the score-correction re-grader must load the in-play markers too"
    # the rule itself: an in-play row is priced at its recorded odds, never the pre-match 'available' quote
    assert public_price({"match_minute_at_pick": 35, "odds_at_pick": 2.4, "odds_at_pick_available": 1.8})[1] == "inplay"


@test("RETIRED-BOTS-NO-NEW-PICKS — a retired bot writes no new picks in ANY writer, standalone paper jobs included (#162)")
def test_retired_bots_no_new_picks():
    """#162 (owner 13A, 2026-09-25). W7.1 gated the pipeline; the verify queue then caught three standalone paper
    jobs (team-total, corners, first-half 1x2 — retired 2026-09-14) still inserting shadow_bets: 53 rows in 2 h.
    Each job's generate_picks now returns before any read/write when bot_status.bot_is_live() is False (fails
    closed); settle_picks is untouched so their existing picks keep settling."""
    import workers.utils.bot_status as bs
    import workers.api_clients.db as db
    o_live, o_w = bs.bot_is_live, db.execute_write
    def _no_write(*a, **k):
        raise AssertionError("a retired bot must not write")
    for mod in ("workers.jobs.team_total_paper_bot", "workers.jobs.corners_paper_bot",
                "workers.jobs.first_half_1x2_paper_bot"):
        m = __import__(mod, fromlist=["x"])
        o_id = m._bot_id
        try:
            m._bot_id = lambda: "00000000-0000-0000-0000-000000000000"
            bs.bot_is_live = _this_thread_only(lambda name: False, o_live)
            db.execute_write = _this_thread_only(_no_write, o_w)
            out = m.generate_picks()
            assert out.get("retired") is True and out["picked"] == 0, (mod, out)
        finally:
            m._bot_id, bs.bot_is_live, db.execute_write = o_id, o_live, o_w

@test("PLACEMENT-FLOOR-ONE-RULE — every placer applies placement_floor.pick_clears to every capable bot")
def test_placement_floor_one_rule():
    """[[#162]] W4.3 (2026-09-25). The UI placer used BOT_THRESHOLDS (selection-blind, 3 pp default for every
    sharp bot); the router stacked the 13 pp market floor on the same bots. One sharp pick passed one
    placer and failed the other. Now both call placement_floor.pick_clears: the stricter of the bot's
    own floor and the market floor (owner decision 3C), plus the bot's own ceilings, fail closed."""
    import inspect
    import scripts.export_bot_config as _ebc
    import scripts.place_coolbet_ui as ui
    import workers.automation.best_price_router as bpr
    import workers.automation.coolbet_ui_placer as up
    from workers.automation import placement_floor as pf

    rules = pf.bot_rules()
    capable = {r["bot_name"] for r in _ebc.build_rows() if r.get("placeable")}
    missing = capable - set(rules)
    assert not missing, f"real-money-capable bots with no placement rule (would all refuse): {sorted(missing)}"

    # The two ex-real-money bots are bit-identical to their pre-W4.3 floors.
    f = pf.placement_floor("bot_coolbet_ou_model_v1", "over_under_25", "over", 2.2, rules)
    assert (f.edge_min, f.odds_min) == (0.08, 1.80), f
    f = pf.placement_floor("bot_coolbet_1x2_model_v1", "1x2", "home", 3.0, rules)
    assert (round(f.edge_min, 10), f.odds_min) == (0.10, 2.80), f
    assert not pf.pick_clears("bot_coolbet_1x2_model_v1", "1x2", "away", 3.5, 0.6, rules)[0], "home only"
    assert not pf.pick_clears("bot_coolbet_1x2_model_v1", "1x2", "home", 2.79, 0.6, rules)[0], "2.80 floor"
    assert pf.pick_clears("bot_coolbet_1x2_model_v1", "1x2", "home", 3.0, 0.1 + 1 / 3.0, rules)[0], "on the floor passes"

    # Decision 3C: the market floor is stacked on every bot unless the OWNER opts it out.
    assert pf.MARKET_FLOOR_OPT_OUT == frozenset(), "an opt-out is a real-money policy change: owner only"
    f = pf.placement_floor("bot_coolbet_trigger_sharp_1x2_v1", "1x2", "draw", 3.4, rules)
    assert f.edge_min == 0.13 and f.odds_min == 2.80, f
    # The bot's own ceilings apply (phantom-price guards the generator enforces).
    assert not pf.pick_clears("bot_trigger_1x2_sharp_tight_v1", "1x2", "home", 2.9, 0.9, rules)[0]
    assert pf.EDGE_UNIT == "pp"

    # Fail closed.
    assert not pf.pick_clears("bot_does_not_exist", "1x2", "home", 3.0, 0.9, rules)[0]
    assert not pf.pick_clears("bot_coolbet_ou_model_v1", "1x2", "home", 3.0, 0.9, rules)[0], "wrong market"
    assert not pf.pick_clears("bot_coolbet_ou_model_v1", "over_under_25", "over", 2.2, None, rules)[0]
    assert ui.bot_edge_floor("bot_does_not_exist") == 1.0

    # Every placer calls it; the old copies are gone.
    assert not hasattr(ui, "BOT_THRESHOLDS"), "BOT_THRESHOLDS is deleted — the rule lives in placement_floor"
    src_ui = inspect.getsource(ui.place_for_bot)
    assert "pick_clears(" in src_ui and "bot_name=bot_name" in src_ui
    src_stage = inspect.getsource(up.stage_bet)
    assert "pick_clears(" in src_stage and "min_odds_to_clear(" in src_stage
    src_route = inspect.getsource(bpr._route)
    assert "clears=lambda" in src_route and "pick_clears(" in src_route and "BOT_THRESHOLDS" not in src_route
    d = bpr.decide_book(0.45, 0.0, 1.0, {"Coolbet": 3.0},
                        clears=lambda o: pf.pick_clears("bot_coolbet_trigger_sharp_1x2_v1", "1x2", "away", o, 0.45, rules))
    assert d["winner"] is None, "a 3 pp sharp away edge must not clear the stacked 13 pp floor"
    # Review round 1: the sharp bots' own outlier cap applies at placement, a one-point window
    # (floor == ceiling) is empty, and both router arms re-check at the live price with the rule.
    assert rules["bot_coolbet_trigger_sharp_1x2_v1"].outlier_mult, "sharp bots carry the outlier cap"
    # Since W7.6 every sharp bot also carries the 8 pp ceiling, so with the stacked floor their windows
    # are EMPTY (refused before any price check). Exercise the outlier cap on a ceiling-free copy.
    import dataclasses as _dc
    _r2 = dict(rules)
    _r2["bot_coolbet_trigger_sharp_1x2_v1"] = _dc.replace(rules["bot_coolbet_trigger_sharp_1x2_v1"], edge_ceiling=None)
    ok, why = pf.pick_clears("bot_coolbet_trigger_sharp_1x2_v1", "1x2", "home", 12.0, 0.30, _r2)
    assert not ok and "outlier cap" in why, why
    ok, why = pf.pick_clears("bot_coolbet_trigger_sharp_1x2_v1", "1x2", "home", 3.2, 0.45, rules)
    assert not ok and "empty edge window" in why, why
    ok, why = pf.pick_clears("bot_trigger_ou_sharp_v1", "over_under_25", "over", 2.0, 0.58, rules)
    assert not ok and "empty edge window" in why, why
    src_cb = inspect.getsource(bpr._dispatch_coolbet)
    assert 'bot_name=pick.get("bot_name")' in src_cb, "router Coolbet arm must pass bot_name to stage_bet"
    src_ub = inspect.getsource(bpr._dispatch_unibet)
    assert "min_odds_to_clear(" in src_ub, "router Unibet arm must floor the live price at the rule's price"

    # Pick queue parity: the web floor map shows each capable bot's OWN generating floor (the
    # manual-placement signal), which must equal the generator's rule — it once fell back to 0.08
    # for a 10% bot. (The stacked real-money floor is exported as the bot_config 'placement_floor' gate.)
    import re as _re
    from pathlib import Path as _P
    web = _P(__file__).resolve().parent.parent.parent / "odds-intel-web" / "src/lib/coolbet-edge.ts"
    if web.exists():
        from workers.automation.coolbet_placer import min_edge_for_pick, _min_odds_for
        wmap = {k: float(v) for k, v in _re.findall(r"^\s+(bot_[a-z0-9_]+):\s*([0-9.]+),", web.read_text(), _re.M)}
        for b in sorted(capable):
            r = rules[b]
            sel = r.selections[0] if r.selections else ("home" if r.markets[0] == "1x2" else "over")
            own = r.edge_floor if r.edge_floor is not None else min_edge_for_pick(
                r.markets[0], sel, _min_odds_for(r.markets[0]))
            assert b in wmap, f"{b} missing from BOT_EDGE_THRESHOLDS (would fall back to 0.08)"
            assert abs(wmap[b] - float(own)) < 1e-9, f"{b}: web {wmap[b]} != generator floor {own}"

@test("REAL-BETS-ONE-WRITER — every engine real_bets insert goes through store_real_bet; bets link to /picks picks")
def test_real_bets_one_writer():
    """[[#162]] W4.5 (2026-09-25). The account-sync reconcile had its own INSERT INTO real_bets beside
    store_real_bet — a second writer that skipped the stake/odds validation — and a bet placed by hand on
    a /picks pick had no link to it. Now: one engine writer, the manual RPC (the web path's only writer)
    takes p_forward_test_pick_id, and the manual route canonicalises vocabulary like the engine."""
    import inspect
    import pathlib as _pl
    import re as _re
    root = _pl.Path(__file__).resolve().parent.parent
    writers = []
    for sub in ("workers", "scripts"):
        for f in (root / sub).rglob("*.py"):
            if f.name == "smoke_test.py" or "archive" in f.parts:
                continue
            if _re.search(r"INSERT\s+INTO\s+real_bets\b", f.read_text(errors="ignore"), _re.I):
                writers.append(str(f.relative_to(root)))
    assert writers == ["workers/api_clients/supabase_client.py"], f"second real_bets writer(s): {writers}"
    from scripts import place_coolbet_ui as m
    src = inspect.getsource(m.reconcile_account_to_real_bets)
    assert "store_real_bet(" in src and "placed_real=True" in src, "account sync must use store_real_bet"
    mig = (root / "supabase/migrations/448_real_bets_forward_test_link.sql").read_text()
    assert "REFERENCES picks_forward_test(id) ON DELETE SET NULL" in mig and "p_forward_test_pick_id" in mig
    assert "DROP FUNCTION IF EXISTS public.record_manual_real_bet" in mig, "no ambiguous overload"
    web = root.parent / "odds-intel-web" / "src/app/api/admin/real-bet/route.ts"
    if web.exists():
        w = web.read_text()
        assert "normalizeMarket(body.market, body.selection)" in w, "manual route must canonicalise vocabulary"
        assert "p_forward_test_pick_id" in w

@test("RULE-VERSION-TAGGED — every new pick carries its bot's rule version (owner decision (b), #162)")
def test_rule_version_tagged():
    """[[#162]] owner decision (b), 2026-09-25: no twins — a live bot's rule changes in place and each
    pick is tagged with the rule it was made under. Source of truth = BotSpec.rule_version; the
    scheduler syncs it to bots.rule_version before any writer runs; a DB trigger stamps new picks."""
    import dataclasses
    import inspect
    import pathlib as _pl
    import re as _re
    from workers.registry.bot_registry import BOTS, BotSpec
    from workers.utils import bot_status as bs
    assert "rule_version" in {f.name for f in dataclasses.fields(BotSpec)}
    bad = [b.name for b in BOTS if not _re.fullmatch(r"r[0-9]+", b.rule_version)]
    assert not bad, f"rule_version must look like r1, r2 …: {bad}"
    root = _pl.Path(__file__).resolve().parent.parent
    mig = (root / "supabase/migrations/453_pick_rule_version.sql").read_text()
    for t in ("simulated_bets", "shadow_bets"):
        assert f"BEFORE INSERT ON {t}" in mig, f"{t} must be stamped by the trigger"
    assert "IF NEW.rule_version IS NULL" in mig, "an explicit tag from a writer must win"
    src = inspect.getsource(bs.sync_rule_versions)
    assert "IS DISTINCT FROM" in src and "except Exception" in src, "idempotent and never raises"
    sched = (root / "workers/scheduler.py").read_text()
    main_src = sched[sched.index("\ndef main():"):]
    i_sync = main_src.index("\n    sync_rule_versions()")
    i_start = main_src.index("\n    _maybe_catchup_missed_settlement()")
    assert i_sync < i_start, "sync must run before the catch-up / any writer"
    assert 'id="rule_version_sync"' in sched

@test("VIP1-EXACT-RULE-ONE-PER-MATCH — VIP #1 runs the pre-registered B2 rule only; one pick per match across runs (#162 W7.7/W7.8)")
def test_vip1_exact_rule_one_per_match():
    """[[#162]] W7.7/W7.8/W8.7 (owner decision (b), 2026-09-25). VIP #1 (bot_combined_1x2_ev5_v1) inherited
    ~8 legacy gates its backtest never tested (they dropped 35 B2-clearing candidates vs 26 accepted in 7
    days), and one_per_match held only within a run (it held home AND away on one fixture). Now: an
    `exact_rule` flag skips every inherited gate for it, and every one_per_match bot skips a match it
    already holds a pending pick on — failing CLOSED if the ledger is unreadable. Both bots are r2."""
    import pathlib as _pl
    from workers.jobs.daily_pipeline_v2 import BOTS_CONFIG
    from workers.registry.bot_registry import BOTS
    exact = sorted(n for n, c in BOTS_CONFIG.items() if c.get("exact_rule"))
    assert exact == ["bot_combined_1x2_ev5_v1"], f"exact_rule is VIP #1's pre-registration, nothing else: {exact}"
    src = (_pl.Path(__file__).resolve().parent.parent / "workers/jobs/daily_pipeline_v2.py").read_text()
    for guard in ("not _exact\n                    and os.getenv(\"ANCHOR_GAP_MID_BAND_ENABLED\"",
                  "if not _exact and _anchor_gap > _veto_gap:",
                  "if not _exact and mkt == \"1X2\" and selection == \"Home\":",
                  "if not _exact and odds_mv[\"veto\"]:",
                  "if os_market != \"1x2\" and not _exact:",
                  "aln_bump = eff_bump = 0.0",
                  "if _min_aln is not None and not _exact:",
                  "stake = FLAT_STAKE_EUR",
                  "if not config.get(\"exact_rule\") and not _meta.should_fire(meta_score):"):
        assert guard in src, f"inherited gate not skipped for the exact-rule bot: {guard!r}"
    # The B2 rule itself is still enforced for it: EV floor, odds range, Pinnacle required.
    c = BOTS_CONFIG["bot_combined_1x2_ev5_v1"]
    assert c["edge_unit"] == "ev" and c["odds_range"] == (1.30, 6.00) and c["require_pinnacle"] and c["one_per_match"]
    assert all(v == {"1x2_fav": 0.05, "1x2_long": 0.05} for v in c["edge_thresholds"].values())
    # One per match across runs, fail closed, and a dedup counts as holding the match.
    i = src.index("W7.8 (rule r2 for every one_per_match bot)")
    blk = src[i:i + 1800]
    assert "result = 'pending'" in blk and "bet_candidates = []" in blk and "Fail closed" in blk
    assert "elif config.get(\"one_per_match\"):\n                        # [[#162]] W7.8: store_bet dedup" in src
    rv = {b.name: b.rule_version for b in BOTS}
    for n, cc in BOTS_CONFIG.items():
        if cc.get("one_per_match") and cc.get("is_active", True) and n in rv:
            assert rv[n] != "r1", f"{n}'s rule changed (W7.8) — its rule_version must be bumped"

